export const RELATION_SOURCE = {"source":"data/hardware-graph.json","originalRelations":115,"nodes":[{"id":"cpu","name":"CPU","category":"연산","summary":"명령을 실행하고 다른 장치의 작업을 조율합니다","detail":"CPU는 컴퓨터 전체의 '지휘 본부'다 RAM에 올라온 프로그램의 기계어 명령을 클럭 박자에 맞춰 가져와(페치) 해석하고(디코드) 실제 계산과 데이터 이동을 수행한다 산술·논리·비교·분기·메모리 접근 같은 범용 연산을 모두 처리하며, GPU·SSD·네트워크 카드 같은 주변 장치에게 언제 무엇을 할지 지시하고 그 결과를 받아 조율하는 총괄 역할도 맡는다 다만 겉보기에는 '순서대로 하나씩' 실행하는 것처럼 보여도, 내부에서는 여러 명령을 동시에·순서를 바꿔가며 병렬로 처리한다 즉 다른 하드웨어가 특정 일에 특화된 전문가라면, CPU는 무엇이든 시키는 대로 하는 만능 일꾼이자 오케스트라의 지휘자다","parts":[{"name":"코어 (Core)","role":"명령을 페치→디코드→실행→라이트백까지 처리하는 완결된 연산 엔진 하나 현대 CPU는 이 코어를 여러 개 담아(멀티코어) 서로 다른 작업을 물리적으로 동시에 처리한다 각 코어는 SMT(하이퍼스레딩)로 논리 스레드 2개(일부 아키텍처는 4·8개)를 굴려 실행 유닛의 빈틈을 메우기도 한다 최근엔 성능 코어(P)와 효율 코어(E)를 섞은 이종(빅·리틀) 구성도 흔하다"},{"name":"ALU (Arithmetic Logic Unit, 산술논리장치)","role":"정수 덧셈·뺄셈, AND/OR/XOR 같은 논리 연산, 크기 비교, 시프트를 담당하는 핵심 계산 회로 한 코어에 여러 개가 있어 정수 연산을 병렬 처리한다 프로그램 대부분의 기본 연산이 여기서 처리된다"},{"name":"FPU (Floating-Point Unit, 부동소수점장치)","role":"소수점이 있는 실수 계산(3.14 × 2.71 등)을 전담한다 물리 시뮬레이션, 3D 그래픽 좌표 변환, 과학 계산에 필수 정수만 다루는 ALU로는 비효율적인 실수 연산을 전용 회로로 빠르게 처리한다 현대 코어에선 이 부동소수점 연산이 SIMD/벡터 유닛과 회로를 공유하는 경우가 많다"},{"name":"SIMD/벡터 실행유닛 (Single Instruction, Multiple Data)","role":"'하나의 명령으로 여러 데이터를 한꺼번에' 계산하는 넓은 연산 유닛(x86의 SSE/AVX/AVX-512, ARM의 NEON/SVE) 예컨대 256비트 폭이면 32비트 실수 8개를 한 명령으로 동시에 더한다 영상·이미지 처리, 오디오 디코딩, AI 추론처럼 같은 연산을 대량 반복하는 일에서 처리량을 몇 배로 올린다"},{"name":"레지스터 파일 (Register File)","role":"CPU 안에서 가장 빠른 초소형 저장소 지금 계산 중인 값·주소를 담는다 x86-64는 프로그램이 보는 범용 레지스터가 16개, ARM64(AArch64)는 31개지만, 실제로는 리네이밍용 물리 레지스터가 수백 개 있어 여러 명령이 서로 안 부딪히게 한다 접근 지연은 대략 1 사이클로 사실상 즉시에 가깝다"},{"name":"제어부 (Control Unit) / 마이크로코드","role":"명령어를 해석해 각 부품에 '언제 무엇을 하라'는 제어 신호를 뿌리는 지휘자 프로그램 카운터를 관리하고 파이프라인의 흐름을 통제한다 아주 복잡하거나 드문 명령은 마이크로코드(칩 안에 저장된 내부 소형 프로그램)로 여러 단계로 풀어 실행한다"},{"name":"명령어 페치 유닛 + 디코더 + 마이크로옵 캐시","role":"페치 유닛이 L1 명령어 캐시에서 명령 비트열을 끌어오고, 디코더가 그것을 실행 유닛이 이해하는 마이크로옵으로 번역한다 마이크로옵 캐시(uop cache)는 이미 디코드해 둔 결과를 담아, 반복되는 코드에서 비싼 디코딩을 건너뛰게 해 준다 x86은 명령 길이가 1~15바이트로 제각각이라 디코딩이 까다롭고, ARM(AArch64)은 4바이트로 고정돼 디코딩이 단순하다"},{"name":"분기 예측기 (Branch Predictor)","role":"조건 분기(if/반복문)에서 어느 방향으로 갈지 과거 이력 패턴으로 예측하고, 분기 목표 버퍼(BTB)·리턴 스택 버퍼로 목적지 주소까지 미리 짚어 페치를 이끈다 현대 예측기의 적중률은 대략 95~99%로 매우 높아, 파이프라인이 갈림길에서 멈추지 않고 계속 달리게 하는 성능의 숨은 주역이다"},{"name":"스케줄러(예약 스테이션) + 재정렬 버퍼(ROB, Reorder Buffer)","role":"비순차 실행의 심장 스케줄러는 입력이 준비된 마이크로옵부터 실행 포트로 내보내 순서를 재배치하고, ROB는 그렇게 뒤죽박죽 끝난 결과를 원래 프로그램 순서대로 은퇴시켜 정확성을 보장한다 ROB는 수백 개의 미완료 명령을 담아 긴 대기를 감춘다"},{"name":"로드/스토어 유닛 (LSU) + 주소 생성 유닛(AGU)","role":"메모리 읽기(load)·쓰기(store) 명령을 처리한다 AGU가 접근할 주소를 계산하고, 로드/스토어 큐와 버퍼로 메모리 접근 순서·의존을 관리한다 캐시와 코어 사이의 데이터 창구다"},{"name":"하드웨어 프리페처 (Hardware Prefetcher)","role":"메모리 접근 패턴(연속·일정 간격 등)을 관찰해, 아직 요청되지 않은 데이터를 미리 캐시로 끌어와 둔다 실제 접근 때 캐시 히트가 되도록 대기 시간을 숨겨, 순차·규칙적 데이터 처리에서 체감 성능을 크게 올린다"},{"name":"L1 / L2 캐시 (코어 전용)","role":"코어 바로 옆에 붙은 초고속 소형 메모리 L1은 명령용·데이터용으로 나뉘어 가장 빠르고(대략 1 ns, 4~5 사이클), L2는 조금 크고 조금 느리다(약 3~4 ns) 자주 쓰는 코드·데이터를 여기 담아 느린 RAM 왕복을 줄인다"},{"name":"L3 캐시 (공유) + 코어 간 인터커넥트(링/메시)","role":"여러 코어가 함께 쓰는 큰 캐시로, 코어들 사이의 데이터 공유·일관성(캐시 코히런스, 예: MESI)의 중심이다 링 버스나 메시 네트워크가 코어·캐시·메모리 컨트롤러를 그물처럼 이어 데이터를 실어 나른다 AMD의 3D V-캐시나 서버 칩은 이 L3를 수십~수백 MB까지 키운다"},{"name":"MMU (Memory Management Unit) + TLB (Translation Lookaside Buffer)","role":"프로그램이 쓰는 가상 주소를 실제 물리 주소로 번역하는 장치 TLB는 최근 번역 결과를 담은 캐시로, 매번 페이지 테이블을 뒤지지(page walk) 않고 빠르게 주소를 변환한다 프로세스 간 메모리 보호와 가상 메모리를 가능케 한다"},{"name":"통합 메모리 컨트롤러 (IMC, Integrated Memory Controller)","role":"예전엔 메인보드 칩셋(노스브리지)에 있던 것이 이제 CPU 안으로 들어온 부품 DRAM(DDR5 등)과 직접 대화하며 읽기/쓰기 타이밍과 채널을 관리한다 CPU 옆에 붙어 있어 메모리 지연이 크게 줄었다"},{"name":"PCIe 컨트롤러 (Peripheral Component Interconnect Express)","role":"GPU·NVMe SSD·네트워크 카드 같은 고속 주변장치와 CPU를 직접 잇는 초고속 통로 여러 개의 '레인'으로 데이터를 병렬 전송하며, IMC와 함께 CPU를 시스템의 데이터 허브로 만든다"},{"name":"클럭 생성기(PLL) + 전압조정·전력관리","role":"PLL(Phase-Locked Loop)이 기준 클럭을 곱해 코어가 쓰는 수 GHz 클럭을 만든다 전력·온도 여유를 보고 클럭·전압을 실시간으로 올리거나(부스트) 낮춰(절전) 성능과 발열·전력의 균형을 맞춘다(DVFS) 온도 한계에서는 스로틀링으로 클럭을 낮춘다"}],"model":"cpu"},{"id":"gpu","name":"GPU","category":"연산","summary":"많은 계산을 병렬로 처리해 화면을 만듭니다","detail":"GPU는 컴퓨터에서 '똑같은 연산을 엄청나게 많이 동시에' 해야 하는 일을 전담하는 처리량(throughput) 중심의 프로세서다 원래는 3D 게임 화면처럼 수백만 개의 픽셀·정점을 병렬로 계산하는 그래픽 렌더링을 위해 만들어졌지만, 같은 대량 병렬 구조가 딥러닝의 행렬 곱셈, 과학 시뮬레이션, 영상 인코딩에도 이상적이라 오늘날 AI 연산의 핵심 장치가 되었다 CPU가 소수의 강력한 코어로 순차적·분기 많은 제어 흐름을 빠르게 처리한다면, GPU는 약한 코어 수천 개로 데이터를 쪼개어 동시에 갈아버린다 컴퓨터 안에서 CPU의 '보조 연산 가속기'이자 화면을 실제로 그려 모니터로 내보내는 '출력 담당'이라는 두 역할을 함께 맡는다(단, 일부 데이터센터 GPU는 디스플레이 출력 없이 연산만 담당한다)","parts":[{"name":"SM/CU (스트리밍 멀티프로세서 / 컴퓨트 유닛)","role":"GPU의 기본 연산 블록 수십~수백 개가 모여 칩을 이루며, 각 SM 안에 셰이더 코어·워프 스케줄러·레지스터·공유 메모리·텐서/RT 코어·텍스처 유닛이 들어 있다 CPU의 '코어'에 해당하는 자족적 연산 단위다"},{"name":"셰이더 코어 (CUDA 코어 / 스트림 프로세서)","role":"실제 산술을 담당하는 수천 개의 작은 ALU. 정점 변환, 픽셀 색 계산, 범용 연산의 덧셈·곱셈을 수행한다 하나하나는 약하지만 수천 개가 동시에 돌아 막대한 처리량을 낸다"},{"name":"워프 스케줄러 & 디스패치 유닛","role":"SM 안에서 준비된 워프(32스레드 묶음)를 골라 매 클럭 셰이더 코어에 명령을 발행한다 메모리 대기 중인 워프 대신 실행 가능한 워프로 즉시 전환해 코어를 놀리지 않게 하는 지연 은닉의 핵심"},{"name":"레지스터 파일","role":"각 스레드가 계산 중인 값을 담아두는 초고속 저장소 GPU는 수천 스레드의 상태를 동시에 유지해야 해서 레지스터 파일이 CPU보다 훨씬 크다(SM당 수백 KB) 이 덕에 워프 전환이 즉각적이다"},{"name":"공유 메모리 / L1 캐시","role":"SM 내부의 작고 빠른 메모리 같은 블록의 스레드들이 데이터를 나눠 쓰거나(공유 메모리), 자주 쓰는 데이터를 캐시해 느린 VRAM 접근을 줄인다 최신 아키텍처는 L1과 공유 메모리를 하나의 통합 영역으로 구성한다"},{"name":"L2 캐시","role":"모든 SM이 공유하는 칩 전체 캐시(수 MB~수십 MB) VRAM보다 훨씬 빠르게 데이터를 재사용하게 해 대역폭 부담과 지연을 줄인다"},{"name":"텐서 코어","role":"작은 행렬(예: 4×4) 타일의 곱셈-누산을 한 번에 처리하는 전용 유닛 딥러닝 학습·추론과 DLSS 같은 AI 화질 향상을 위해 FP16/BF16/FP8(신형은 FP4)·INT8 저정밀 연산을 셰이더 코어보다 수십 배 빠르게 수행한다"},{"name":"RT 코어 (레이 트레이싱 코어)","role":"광선이 3D 장면의 물체(삼각형)와 어디서 만나는지 계산하는 전용 하드웨어 가속 구조(BVH) 순회와 광선-삼각형 교차 판정을 담당해 사실적인 반사·그림자·전역 조명을 실시간으로 가능하게 한다"},{"name":"래스터라이저 (래스터 엔진)","role":"삼각형(벡터 도형)을 화면 격자의 픽셀 조각(프래그먼트)으로 변환하는 고정 기능 하드웨어 어떤 픽셀이 도형에 덮이는지 판정해 셰이딩할 대상을 만든다"},{"name":"텍스처 유닛 (TMU, 텍스처 매핑 유닛)","role":"VRAM에 저장된 이미지(텍스처)를 읽어 화면 픽셀에 입힌다 확대·축소·기울기에 맞춰 여러 텍셀을 섞는 필터링(바이리니어·트라이리니어·이방성 등)으로 매끄러운 표면을 만든다"},{"name":"ROP (래스터 연산 유닛 / 렌더 출력 유닛)","role":"셰이딩이 끝난 픽셀에 대해 깊이·스텐실 테스트, 색 블렌딩, 안티에일리어싱을 적용하고 최종 결과를 프레임버퍼에 기록한다 물체 앞뒤 관계와 투명도를 올바르게 합성한다"},{"name":"메모리 컨트롤러","role":"VRAM(GDDR/HBM)과 GPU 코어 사이의 데이터 통로 여러 개의 메모리 채널을 병렬로 관리해 초당 수백 GB~수 TB의 데이터를 코어에 공급한다 GPU 성능은 이 대역폭에 크게 좌우된다"},{"name":"VRAM (그래픽 메모리, GDDR6/6X/7 또는 HBM3/3e)","role":"텍스처·정점·프레임버퍼·신경망 가중치 등 GPU가 다루는 대용량 데이터를 담는 전용 고속 메모리 시스템 RAM보다 훨씬 넓은 대역폭에 최적화되어 있다"},{"name":"비디오 인코더/디코더 (NVENC / NVDEC 등)","role":"H.264·HEVC·AV1·VP9 같은 동영상 코덱을 하드웨어로 압축(인코딩)·복원(디코딩)하는 전용 블록 셰이더 코어를 쓰지 않고 저전력으로 영상 스트리밍·녹화·화상회의를 처리한다"},{"name":"디스플레이 엔진","role":"완성된 프레임버퍼를 읽어 모니터가 이해하는 신호(HDMI·DisplayPort)로 변환해 내보낸다 재생 주파수, 다중 모니터, 가변 주사율, HDR 출력을 관리한다"},{"name":"PCIe ×16 인터페이스 (호스트 인터페이스)","role":"GPU 카드를 메인보드·CPU와 연결하는 통로 16개 레인으로 명령과 데이터를 주고받는다 게임 중에는 여유롭지만 대용량 데이터를 CPU↔GPU로 자주 옮기는 AI 작업에서는 병목이 되기도 한다"},{"name":"NVLink / 고속 인터커넥트","role":"여러 GPU를 PCIe보다 훨씬 넓은 대역폭으로 직접 연결하는 데이터센터용 통로(예: NVLink, AMD Infinity Fabric) 거대한 AI 모델을 여러 GPU에 나눠 학습·추론할 때 GPU 간 데이터 공유 병목을 줄인다"},{"name":"전원부(VRM)·쿨러·팬","role":"그래픽카드 기판에서 실제로 보이는 부분 VRM은 PCIe·보조 전원의 전기를 GPU가 쓰는 안정된 저전압·고전류로 변환하고, 방열판·히트파이프·팬은 수백 W의 발열을 식힌다 GPU 칩 자체가 아니라 '그래픽카드'를 구성하는 요소다"},{"name":"커맨드 프로세서 / 전역 스케줄러 (GigaThread 엔진·그리드 관리 유닛)","role":"PCIe로 들어온 명령 스트림(드로우 콜·컴퓨트 커널)을 해석하고, 렌더링·연산 작업을 워프·스레드 블록 단위로 잘게 나눠 유휴 SM들에 분배하는 칩 전면부(프론트엔드) 수백 개 SM을 항상 꽉 채워 돌리도록 작업을 조율하는 GPU의 '작업 지휘소'다 '작동 방식' 1~2단계에 등장하지만 주요 부품 표에는 빠져 있어, SM에 일감을 뿌리는 이 핵심 블록을 표에 명시할 필요가 있다"}],"model":"gpu"},{"id":"npu","name":"NPU","category":"연산","summary":"신경망 계산을 효율적으로 수행합니다","detail":"NPU는 CPU·GPU와 함께 SoC(시스템 온 칩) 안에 들어가는 도메인 특화 연산 장치로, 딥러닝 모델의 추론(inference)을 주로 담당한다(데이터센터용 대형 NPU/TPU는 학습도 수행) CPU가 프로그램의 흐름을 지휘하고 GPU가 그래픽·범용 병렬 연산을 맡는 동안, NPU는 신경망에서 압도적 비중을 차지하는 곱셈-누산(MAC) 기반의 무거운 텐서 연산을 전담해(활성함수·정규화 등 나머지는 내부 벡터 유닛이 처리) 같은 일을 훨씬 적은 전력으로 처리한다 핵심 가치는 절대 최고 속도가 아니라 '전력당 성능(TOPS/W)'이다 그래서 배터리로 동작하는 노트북·스마트폰에서 음성 인식, 얼굴 인식, 실시간 영상 처리, 온디바이스 AI 같은 상시(always-on) AI 기능을 발열과 배터리 부담을 최소화하며 돌리는 것이 NPU의 존재 이유다","parts":[{"name":"MAC 배열 / PE 어레이 (Systolic Array 등)","role":"NPU의 심장 곱셈-누산(MAC)을 수행하는 수천~수만 개의 처리 요소(PE)가 2차원 격자로 배열되어 행렬곱·합성곱을 대량 병렬로 처리한다 데이터가 격자를 규칙적으로 통과하는 시스톨릭 어레이(TPU식)가 대표적이지만, SIMD/벡터 기반 타일형 MAC 엔진, 도트-프로덕트 엔진 등 다른 조직을 쓰는 NPU도 많다"},{"name":"처리 요소 (PE, Processing Element)","role":"어레이를 이루는 최소 연산 단위 각 PE는 매 클럭 곱셈 1회 + 덧셈 1회(1 MAC)를 수행하고, 계산한 부분합을 이웃 PE로 넘겨 누적을 이어간다 내부에 소형 레지스터(가중치·부분합 보관)를 가진다"},{"name":"온칩 SRAM (통합 버퍼 / 스크래치패드)","role":"가중치·입력·중간 활성값을 담아두는 칩 내부 고속 메모리 DRAM보다 훨씬 빠르고 에너지가 저렴해, 데이터를 여기 올려두고 반복 재사용함으로써 값비싼 외부 메모리 접근을 줄인다 NPU 효율의 상당 부분이 이 SRAM 활용과 데이터 재사용에서 나온다"},{"name":"누산기 / 부분합 레지스터 (Accumulator)","role":"행렬곱 과정에서 생기는 부분합을 쌓아 최종 합을 만드는 저장소 저정밀 입력(예: INT8×INT8)을 곱한 결과가 넘치지 않도록 보통 더 넓은 비트폭(예: INT32)으로 누적한다"},{"name":"벡터 / 활성함수 유닛 (Special Function Unit)","role":"MAC 배열이 못 하는 비선형·요소별 연산을 담당 ReLU·GELU·softmax·풀링·정규화(LayerNorm 등)와 element-wise 연산을 처리해 레이어 출력을 완성한다"},{"name":"양자화 / 역양자화 유닛 (Quantization Unit)","role":"부동소수점과 저정밀 정수 사이를 변환한다 스케일(scale)과 제로포인트(zero-point)를 적용해 INT8/INT4로 낮추거나, 누적 결과를 다음 레이어 범위로 재양자화·정상 범위로 역양자화한다 저전력 정수 연산과 정확도 사이를 잇는 다리"},{"name":"DMA 엔진 (Direct Memory Access)","role":"CPU 개입 없이 시스템 DRAM과 온칩 SRAM 사이로 가중치·활성값 블록을 옮긴다 연산과 데이터 이동을 겹쳐(double-buffering) 어레이가 놀지 않게 데이터를 계속 공급한다"},{"name":"제어기 / 명령 시퀀서 (Control Sequencer)","role":"컴파일된 모델 명령을 명령/가중치 프리페치 버퍼에서 해석해 '언제 어떤 데이터를 어느 버퍼에서 어레이로 흘릴지'를 지휘한다 NPU 전체의 타이밍과 데이터플로우를 조율하는 지휘자"},{"name":"온칩 인터커넥트 / SoC 버스 인터페이스 (NoC·AXI)","role":"NPU 내부 타일 간, 그리고 NPU와 SoC의 CPU·메모리 컨트롤러를 잇는 고속 배선 이를 통해 시스템 통합 메모리를 CPU·GPU와 공유한다"},{"name":"클럭 · 전력 관리 유닛 (Power/Clock Management, DVFS·클럭 게이팅)","role":"동작 클럭·전압을 부하에 맞춰 조절(DVFS)하고 쓰지 않는 블록의 클럭을 끈다(클럭 게이팅) 웨이크워드 감지 같은 상시(always-on) 작업을 극저전력으로 유지하는 데 핵심이라, 전력당 성능이 생명인 NPU에서 특히 중요하다"},{"name":"가중치 압축·희소성 처리 유닛 (Sparsity / Decompression)","role":"많은 신경망 가중치가 0이거나 압축 가능하다는 점을 이용해, 0을 건너뛰거나 압축된 가중치를 풀어 실제 계산량·메모리 대역폭을 줄인다(모든 NPU에 있는 것은 아님)"}],"model":"npu"},{"id":"sram","name":"캐시","category":"메모리","summary":"자주 쓰는 정보를 연산 장치 가까이에 보관합니다","detail":"SRAM은 CPU가 매 클럭 손을 뻗는 극소량·초고속 저장소를 담당한다 연산 유닛(ALU) 바로 옆의 레지스터 파일, 그리고 그 뒤를 받치는 L1/L2/L3 캐시가 모두 SRAM 계열로 만들어진다(단, 레지스터 파일은 동시 다중 읽기/쓰기를 위해 표준 단일포트 6T가 아니라 다중포트 셀 — 흔히 8T 이상 — 로 구성된다) 코어는 빠른데 주기억장치(DRAM)는 수백 사이클씩 느리다는 '메모리 벽' 문제를, 자주 쓰는 데이터를 코어 근처에 붙잡아 두어 메운다 덕분에 대부분의 접근이 몇 사이클 안에 끝나고, 프로그램이 이론이 아니라 체감 속도로 돌아간다","parts":[{"name":"교차결합 인버터 쌍 (cross-coupled inverters, 래치)","role":"인버터 두 개의 출력을 서로의 입력에 물려 만든 쌍안정 회로(트랜지스터 4개) 1비트를 두 가지 안정 상태(Q=1/Q̄=0 또는 그 반대)로 붙들며, 전원이 켜져 있는 한 되먹임으로 값을 스스로 지탱한다 셀의 심장이다"},{"name":"접근(패스) 트랜지스터 2개","role":"래치의 두 내부 노드(Q, Q̄)를 각각 비트라인에 연결하는 문지기 워드라인이 열릴 때만 통해서, 평소엔 셀을 외부와 격리해 값을 보호하고 접근 시에만 읽기·쓰기를 허용한다 인버터 2개(트랜지스터 4개) + 접근 트랜지스터 2개 = 6T 셀"},{"name":"워드라인 (word line, 행 선택선)","role":"한 행(같은 인덱스의 셀들)의 접근 트랜지스터를 동시에 여닫는 가로선 디코더와 워드라인 드라이버가 딱 한 줄만 활성화해 접근할 행을 지정한다"},{"name":"비트라인 쌍 (bit line, BL / BL̄)","role":"셀에서 데이터를 실어 나르는 세로선 두 가닥(참·반전) 읽을 땐 셀이 만든 미세 전압차를 감지증폭기로, 쓸 땐 드라이버가 몬 값을 셀로 전달하는 통로다"},{"name":"행 디코더 (row decoder)","role":"주소의 인덱스 비트를 받아 수많은 워드라인 중 정확히 하나만 HIGH로 만든다 n비트 인덱스를 2ⁿ개의 행 선택으로 변환한다"},{"name":"열 디코더 / 멀티플렉서 (column decoder/mux)","role":"활성화된 행에서 나온 여러 열 중 실제로 읽거나 쓸 열(오프셋에 해당하는 바이트/워드)을 골라 입출력 경로에 연결한다"},{"name":"프리차지 회로 (precharge)","role":"읽기 직전 두 비트라인을 같은 HIGH 전압으로 미리 충전해 균형을 맞춘다 이 균형이 있어야 셀이 만드는 작은 불균형을 감지증폭기가 빠르고 정확히 읽는다"},{"name":"감지 증폭기 (sense amplifier)","role":"비트라인 사이의 수십 mV 수준 미세 차이를 완전한 0/1 로직 레벨로 순식간에 증폭한다 SRAM이 빠른 큰 이유 중 하나 — 셀이 비트라인을 끝까지 흔들 때까지 기다리지 않는다"},{"name":"쓰기 드라이버 (write driver)","role":"쓸 값을 비트라인에 강하게 실어, 셀의 자기유지 되먹임을 힘으로 눌러 래치를 원하는 상태로 뒤집는다 셀 트랜지스터 크기(쓰기 용이성)와 균형을 이뤄야 한다"},{"name":"데이터 어레이 (data array)","role":"실제 캐시 라인(예: 64바이트) 데이터를 담는 SRAM 셀들의 본체 캐시 용량의 대부분을 차지한다"},{"name":"태그 어레이 (tag array)","role":"각 라인의 상위 주소(태그)를 저장하는 별도의 작은 SRAM. 부적중/적중 판정에 쓰이며, 데이터 어레이와 병렬로 읽혀 지연을 줄인다"},{"name":"유효비트·수정비트·일관성 상태 비트 (valid / dirty / coherence state)","role":"유효비트는 라인에 진짜 데이터가 들었는지, 수정비트는 값이 바뀌어 하위 계층과 달라졌는지(라이트백 필요 여부)를 표시한다 멀티코어 캐시는 여기에 MESI 등 일관성 상태(Modified/Exclusive/Shared/Invalid)도 함께 둔다"},{"name":"태그 비교기 (comparator)","role":"세트 안 각 후보 라인의 저장 태그와 요청 주소 태그를 동시에 비교해 일치 여부를 내보낸다 완전연관·고연관일수록 비교기가 많이 필요해 비싸진다"},{"name":"교체 상태 비트 (LRU / pseudo-LRU state)","role":"집합연관 캐시에서 한 세트 안 라인들의 최근 사용 순서를 근사해 기록한다 부적중 시 어느 라인을 내보낼지 교체 정책이 이 비트로 결정한다"},{"name":"MSHR (미해결 부적중 처리 레지스터)","role":"논블로킹 캐시가 진행 중인 부적중 요청들을 추적하는 작은 표 부적중이 나도 코어를 멈추지 않고 다른 명령을 계속 실행하며, 여러 부적중을 동시에 처리하고 도착한 데이터를 대기 중인 명령에 되돌려 준다"},{"name":"쓰기(스토어) 버퍼 (store/write buffer)","role":"쓰기 요청을 잠시 담아 두어, 코어가 하위 계층 쓰기 지연을 기다리지 않고 진행하게 한다 라이트백·라이트스루 트래픽을 흡수·병합한다"},{"name":"ECC·패리티 로직 (error correction / parity)","role":"미세 공정에서 늘어나는 소프트 에러(비트 뒤집힘)를 검출·정정한다 큰 캐시(특히 L2/L3)는 SECDED 같은 ECC로, 일부 L1은 패리티로 보호한다"},{"name":"출력 드라이버·래치","role":"감지·선택된 데이터를 안정된 신호로 정형해 코어(또는 상위 캐시)로 내보낸다"}],"model":"sram"},{"id":"dram","name":"RAM","category":"메모리","summary":"실행 중인 프로그램과 데이터를 펼쳐 둡니다","detail":"DRAM은 CPU와 저장장치(SSD/HDD) 사이에서 '지금 실행 중인' 코드와 데이터를 담아 두는 작업 공간이다 CPU 캐시(SRAM)보다는 느리지만 용량이 훨씬 크고 값이 싸며, SSD보다는 압도적으로 빨라서 수 GB~수십 GB 규모의 주기억장치로 쓰인다 프로그램을 실행하려면 먼저 저장장치의 내용을 DRAM으로 올려야 하고, CPU는 캐시에 없는 데이터를 이 DRAM에서 읽어 온다 전원이 끊기면 내용이 즉시 사라지는 휘발성이라, 영구 보관은 SSD/HDD의 몫이고 DRAM은 어디까지나 '실행 중 임시 작업대'다","parts":[{"name":"저장 커패시터 (storage capacitor)","role":"전하가 차 있으면 1, 비어 있으면 0 — 딱 1비트를 담는 초소형(펨토패럿급) 전하 저장소 DRAM 셀의 실제 '기억' 부분"},{"name":"접근 트랜지스터 (access transistor)","role":"워드라인 신호로 켜지고 꺼지는 스위치 커패시터를 비트라인에 연결(읽기/쓰기)하거나 끊어(보관) 준다 커패시터와 함께 '1T1C' 셀을 이룬다"},{"name":"워드라인 (wordline, 행 선)","role":"한 행에 속한 모든 셀의 접근 트랜지스터 게이트를 동시에 켜는 가로 배선 활성화할 '행'을 고르는 선"},{"name":"비트라인 (bitline, 열 선)","role":"켜진 셀의 전하를 센스앰프까지 실어 나르는 세로 배선 읽기 전 VDD/2로 프리차지돼 있다가 미세 전압 변화가 여기서 나타난다"},{"name":"센스앰프 (sense amplifier)","role":"비트라인의 극히 작은 전압 차이를 감지해 완전한 0/1로 증폭·래치하고 셀에 값을 복원한다 사실상 '활성 행 버퍼' 역할을 겸한다"},{"name":"행 디코더 / 열 디코더","role":"컨트롤러가 보낸 주소를 해독해 정확히 하나의 워드라인(행)과 원하는 열을 선택한다"},{"name":"뱅크 (bank)","role":"독립적으로 행을 열고 닫을 수 있는 셀 배열 단위 각자 자신의 행 버퍼를 가져, 여러 뱅크가 동시에 다른 행을 다룰 수 있게 한다"},{"name":"뱅크 그룹 (bank group)","role":"뱅크들을 묶은 상위 단위 연속 접근을 그룹끼리 나눠 처리해 병렬성을 높인다(DDR4/DDR5의 핵심 구조)"},{"name":"리프레시 카운터/로직","role":"다음에 되살릴 행 주소를 추적해, REFRESH 명령이 올 때마다 해당 행 묶음을 순회시켜 전 행이 보존시간 안에 빠짐없이 리프레시되도록 한다"},{"name":"모드 레지스터 (Mode Register)","role":"CAS Latency, 버스트 길이, 구동 옵션 등 칩의 동작 설정을 담아 두는 설정 레지스터 부팅 초기화(트레이닝) 때 값이 쓰인다"},{"name":"I/O 버퍼 / 프리페치 버퍼와 DQ 데이터 핀","role":"내부에서 넓게 프리페치한 비트를 모아 두었다가 칩 안팎으로 실제 데이터를 주고받는 관문 DDR의 양 엣지 전송이 여기서 일어난다"},{"name":"명령/주소(CA)·제어 버스 인터페이스","role":"CS·클럭·명령/주소 등 제어·주소 신호를 받아들이는 입력부 데이터 버스(DQ)와 분리돼 있다"},{"name":"(DDR5 칩) 온다이 ECC(ODECC) 엔진","role":"DDR5부터 모든 칩에 의무 탑재 대략 128비트 데이터당 8비트 패리티로 칩 내부의 단일 비트 오류를 스스로 정정해 미세공정 결함을 감춘다 모듈 밖 사이드밴드 ECC와는 별개·상호보완"},{"name":"(모듈) PCB와 금도금 엣지 커넥터 핀","role":"여러 DRAM 칩을 얹어 슬롯에 꽂는 기판과 접점 DDR5 DIMM은 288핀, SO-DIMM은 262핀"},{"name":"(모듈) SPD EEPROM","role":"모듈의 용량·표준 타이밍·제조사 정보와 XMP/EXPO 오버클록 프로필을 담은 작은 칩 부팅 시 BIOS/펌웨어가 읽어 메모리 설정을 자동으로 잡는다"},{"name":"(DDR5 모듈) PMIC 전력관리 IC","role":"DDR5부터 모듈 위에 올라온 전원 관리 칩 메인보드가 아니라 모듈 자체에서 필요한 전압을 만들고 다스린다"},{"name":"(서버 모듈) RCD 레지스터 클록 드라이버 / 데이터 버퍼","role":"RDIMM은 주소·명령을 RCD가 한 번 받아 재구동(버퍼링)해 전기 부하를 줄여 랭크를 많이 꽂게 한다 LRDIMM은 데이터 라인까지 버퍼링해 초대용량을 지원한다"},{"name":"(모듈) 노치(키)·히트 스프레더·선택적 ECC 칩","role":"노치는 세대·방향 오삽입을 막는 홈, 히트 스프레더는 방열, ECC 칩은 오류 검출·정정용 여분 폭을 제공한다(비ECC 64비트 → DDR4 ECC 72비트 / DDR5 ECC 80비트)"}],"model":"dram"},{"id":"vram","name":"VRAM","category":"메모리","summary":"그래픽과 AI 연산에 필요한 정보를 담습니다","detail":"VRAM은 GPU가 매 순간 소비하는 방대한 데이터(렌더링할 텍스처·기하 정보, 화면 픽셀을 담는 프레임버퍼와 깊이 버퍼, 신경망의 가중치와 중간 활성값·KV 캐시)를 담아두는 GPU 전용 작업 기억장치다 GPU는 수천~수만 개의 연산 유닛이 동시에 데이터를 요구하기 때문에, 한 번에 조금씩 빠르게 왕복하는 시스템 RAM과 달리 '한 번에 아주 넓게' 데이터를 실어나르는 능력이 필요하다 그래서 VRAM은 넓은 메모리 버스와 초고속 신호 기술로 시스템 RAM보다 대략 10~20배(데이터센터급 HBM에선 그 이상) 큰 대역폭을 제공하도록 설계된다 개별 접근의 지연시간(레이턴시)을 줄이기보다 총 처리량을 극대화하고, 그 대기 시간은 GPU가 수많은 스레드를 번갈아 실행해 숨기는 것이 설계 철학이다","parts":[{"name":"DRAM 셀 어레이 (뱅크·뱅크 그룹)","role":"'커패시터 1개 + 트랜지스터 1개'로 된 셀이 행과 열의 격자로 배열된 저장 본체 여러 뱅크·뱅크 그룹으로 나뉘어 서로 다른 뱅크를 겹쳐 접근함으로써 사실상 병렬로 동작해 처리량을 높인다"},{"name":"감지증폭기(Sense Amplifier)와 로우 버퍼","role":"셀 커패시터의 아주 약한 전하 차이를 감지해 또렷한 0/1로 증폭하고 한 행 전체를 임시로 붙잡아 둔다 같은 행 안의 연속 접근이 빠른 이유가 바로 이 버퍼에 이미 데이터가 올라와 있기 때문이다"},{"name":"행/열 디코더 & 주소 로직","role":"컨트롤러가 준 주소를 해석해 어느 행을 열고 어느 열을 읽을지 고른다 ACTIVATE로 행을 선택하고 READ/WRITE로 열을 지정하는 2단계 접근을 담당한다"},{"name":"I/O 인터페이스(PHY)와 DQ 데이터 핀","role":"칩 안팎을 잇는 초고속 물리계층 내부의 넓고 느린 데이터를 바깥의 좁고 빠른 핀 신호로 직렬화하고, GDDR6X의 PAM4·GDDR7의 PAM3 인코더/디코더, 온다이 종단(ODT), 데이터 클럭(WCK) 회로가 여기 모여 있다"},{"name":"명령·주소(CA) 버스와 데이터(DQ) 버스","role":"명령/주소는 CA 선으로, 실제 데이터는 DQ 선으로 나뉘어 흐른다 이 DQ 핀들이 여러 칩에 걸쳐 모여 128~512비트에 이르는 '넓은 메모리 버스'를 이루며, 이 버스 폭은 핀당 속도와 함께 대역폭을 결정하는 두 축 중 하나다"},{"name":"프리페치·직렬화 버퍼","role":"느린 셀 어레이에서 한 번에 넓게 읽어온 데이터를 잠시 담았다가 핀 속도에 맞춰 순서대로 내보낸다 코어 클럭과 인터페이스 클럭의 큰 속도 차이를 메우는 완충 장치다"},{"name":"리프레시 회로 & 클럭 생성(PLL/DLL)","role":"커패시터 전하가 새기 전에 주기적으로 모든 행을 재충전하고, 초고속 데이터 전송의 타이밍을 맞추는 기준 클럭을 만들어 신호가 정확한 순간에 도착하도록 정렬한다"},{"name":"온다이 ECC & 데이터 무결성 로직","role":"GDDR6 이후 세대는 셀 미세화로 늘어난 비트 오류를 칩 내부에서 스스로 검출·정정하는 온다이 ECC를 갖는다 HBM은 여기에 더해 별도 신호선으로 시스템 단 ECC까지 지원해, 장시간 돌아가는 AI·데이터센터에서 데이터 신뢰성을 확보한다"},{"name":"BGA 패키지와 PCB 실장(GDDR의 경우)","role":"GDDR 칩은 GPU를 둘러싸고 기판(PCB)에 직접 납땜된다 DIMM 소켓 없이 짧은 배선으로 GPU에 붙는 이 구조 덕분에 신호 무결성이 좋아 높은 핀 속도를 견딘다 기판 앞뒤 양면에 칩을 마주 붙이는 클램셸(clamshell) 실장으로 버스폭은 그대로 두고 용량만 2배로 늘리기도 한다"},{"name":"TSV(관통 실리콘 비아) — HBM","role":"HBM에서 여러 층으로 쌓인 DRAM 다이를 수직으로 꿰뚫어 전기적으로 잇는 미세 구멍 층과 층을 옆이 아니라 위아래로 직결해, 아주 넓은 1024/2048비트 통로를 짧은 거리로 만들어 준다"},{"name":"베이스 로직 다이 & 마이크로범프 — HBM","role":"HBM 스택 맨 아래에서 스택 전체의 입출력을 총괄하는 논리 층 그 위 DRAM 다이들과는 마이크로범프(초소형 접점)로 연결되며, 여기서 나온 넓은 신호가 인터포저로 전달된다"},{"name":"실리콘 인터포저 (2.5D 패키징) — HBM","role":"GPU 다이와 HBM 스택을 나란히 얹고 그 사이에 수천 가닥의 초미세 배선을 새긴 실리콘 받침판 일반 PCB로는 불가능한 1024~2048비트급 초광폭 배선을 짧게 잇는 '고속도로 인터체인지' 역할을 한다"},{"name":"메모리 컨트롤러 (GPU 다이 내부, 논리적 구성)","role":"VRAM 칩 자체는 아니지만 짝을 이루는 필수 요소 요청을 모으고 재정렬하며 명령을 발행하고 리프레시를 관리한다 컨트롤러의 채널 수와 폭이 실제로 몇 개의 메모리 칩을 병렬로 부릴 수 있는지를 정한다"}],"model":"vram"},{"id":"ssd","name":"SSD","category":"저장장치","summary":"파일을 플래시 메모리에 보관합니다","detail":"SSD는 전원이 꺼져도 데이터를 유지하는 컴퓨터의 영구 저장 계층(보조기억장치)이다 OS·프로그램·파일이 평소 잠들어 있는 곳으로, CPU가 다룬 데이터는 결국 RAM을 거쳐 SSD로 내려가고 필요할 때 다시 RAM으로 끌어올려진다 HDD와 달리 기계적 탐색(seek)이 없어 접근 지연이 수백 배 짧고, 이 속도가 부팅·앱 실행·파일 열기·게임 로딩의 체감 속도를 좌우한다 다만 플래시는 '덮어쓰기 불가·블록 단위 소거'라는 독특한 제약이 있고 전하가 시간이 지나면 새어 나가므로, 컨트롤러 펌웨어(FTL)가 이 제약과 마모·오류를 감춰 일반 디스크처럼 보이게 만드는 것이 SSD의 본질이다","parts":[{"name":"NAND 플래시 셀 (플로팅 게이트/CTF 트랜지스터)","role":"데이터를 저장하는 최소 단위 절연된 도체 게이트(플로팅 게이트)나 절연체 전하 포집층(CTF)에 전자를 가둬 트랜지스터의 문턱전압을 바꿔 비트를 기억한다 전원이 없어도 전하가 남아 비휘발성이지만, 전하는 시간이 지나면 서서히 새어 나간다"},{"name":"NAND 플래시 다이·패키지","role":"셀이 페이지·블록·플레인 계층으로 조직된 실제 메모리 칩 다이 안에는 셀을 읽고 쓰는 동안 데이터를 담는 페이지 버퍼(센스앰프/페이지 레지스터)가 있다 여러 다이를 한 패키지에 쌓고, 보드에 여러 패키지를 얹어 용량을 만든다 최신은 셀을 수직으로 쌓은 3D NAND(200단 이상)"},{"name":"SSD 컨트롤러 (SoC)","role":"SSD의 두뇌 대개 멀티코어 ARM 프로세서로, FTL 매핑·ECC·웨어 레벨링·가비지 컬렉션·큐 관리·암호화를 모두 실행한다 채널 병렬성을 조율해 성능을 뽑아낸다"},{"name":"다채널 플래시 인터페이스","role":"컨트롤러와 NAND를 잇는 8~16개의 병렬 채널(ONFI/Toggle DDR 규격) 여러 다이를 동시에 굴려 개별 소자의 느림을 대역폭으로 만회한다"},{"name":"DRAM 캐시","role":"FTL 매핑 테이블과 쓰기 버퍼를 담는 고속 임시 메모리 페이지 단위 매핑 기준 대략 용량 1TB당 1GB DRAM 비율 DRAM-less 제품은 이를 생략하고 HMB(호스트 RAM 일부)로 대체한다"},{"name":"FTL (펌웨어 계층)","role":"논리 주소(LBA)를 물리 위치로 바꾸는 소프트웨어 계층 매핑·GC·웨어 레벨링·배드블록 관리 정책을 담당한다 물리 칩이 아니라 컨트롤러가 실행하는 논리 구성요소"},{"name":"ECC 엔진 (LDPC 디코더)","role":"셀에서 읽은, 미세하게 어긋난 신호의 비트 오류를 정정하는 하드웨어 실패하면 기준 전압을 옮겨 다시 읽는 read-retry, 연판정(soft-decision) 디코딩과 함께 TLC/QLC처럼 전압 구간이 촘촘한 고밀도 셀의 신뢰성을 떠받치는 핵심"},{"name":"호스트 인터페이스 (PCIe PHY + NVMe 프론트엔드)","role":"메인보드와 연결되는 관문 PCIe 레인으로 데이터를 실어 나르고, NVMe 프로토콜로 제출/완료 큐와 도어벨을 처리한다 (SATA SSD는 SATA PHY + AHCI를 사용.)"},{"name":"전원관리(PMIC)와 전력손실 보호 커패시터","role":"여러 내부 전압을 안정적으로 공급한다 엔터프라이즈·일부 제품은 커패시터(PLP)로 정전 순간 버퍼에 남은 데이터를 마저 기록해 손실을 막는다"},{"name":"온다이 차지 펌프","role":"NAND 다이 내부 회로 프로그램/소거에 필요한 고전압(대략 15~25V)을 낮은 공급전압에서 만들어낸다 Fowler-Nordheim 터널링으로 전자를 절연막 너머로 밀어 넣거나 빼내는 데 쓰인다"},{"name":"PCB 기판과 폼팩터 커넥터 (M.2 등)","role":"부품을 얹고 신호를 배선하는 보드 M.2 2280 같은 폼팩터의 키/노치로 메인보드 슬롯에 꽂혀 물리·전기적으로 연결된다"},{"name":"펌웨어·메타데이터 영역","role":"컨트롤러 동작 규칙과 매핑 테이블 스냅샷, 배드블록 목록, 마모 통계 등을 NAND 예약 영역에 보관해 재부팅 후에도 상태를 복원한다"},{"name":"온도 센서·서멀 스로틀링 로직 (+선택 방열판)","role":"컨트롤러·NAND 온도를 감시해 임계 온도를 넘으면 성능을 낮춰(throttle) 소자를 보호한다 고속 PCIe 4.0/5.0 NVMe는 발열이 커 방열판(히트싱크)이 흔히 필요하고, 방열 여부가 대용량 연속 쓰기의 지속 성능을 좌우한다"}],"model":"ssd"},{"id":"hdd","name":"HDD","category":"저장장치","summary":"회전하는 디스크에 많은 데이터를 보관합니다","detail":"전원을 꺼도 사라지면 안 되는 대용량 데이터(운영체제, 프로그램, 사진·영상, 백업 아카이브)를 아주 낮은 비용으로 보관하는 2차 저장장치다 접근 지연시간(latency) 기준으로 RAM보다 수만~수십만 배 느리지만(대역폭 격차는 그보다 훨씬 작다), GB당 가격이 압도적으로 싸고 단일 드라이브 용량이 커서, 속도가 덜 중요한 대용량·콜드(cold) 데이터와 데이터센터 벌크 스토리지의 주력으로 남아 있다 SSD가 등장한 뒤 부팅·시스템 디스크 자리는 대부분 내주었지만, \"많이·오래·싸게 담는\" 아카이브 영역에서는 여전히 대체가 어렵다 기계 부품(모터·헤드)이 실제로 움직이는, 현대 PC에서 몇 안 남은 정밀 기계식 장치라는 점이 SSD와의 본질적 차이다","parts":[{"name":"자기 플래터 (magnetic platter)","role":"알루미늄 합금 또는 유리 기판에 코발트계 자성 박막을 입힌 원판 표면의 자화 방향으로 실제 데이터를 저장한다 보통 양면을 쓰며 여러 장을 축에 겹쳐 용량을 늘린다(대용량은 유리 기판이 늘어나는 추세)"},{"name":"스핀들 모터 (spindle motor)","role":"플래터 묶음을 5400/7200 RPM 등 일정 속도로 회전시키는 브러시리스 DC 모터 진동·소음을 줄이려 유체 동압 베어링(FDB)을 쓴다 회전이 균일해야 부양과 타이밍이 안정된다"},{"name":"리드/라이트 헤드 (read/write head)","role":"한 슬라이더에 쓰기용 유도 코일과 읽기용 자기저항(TMR/GMR) 센서가 함께 실린 부품 쓰기 헤드는 자기장으로 자구를 뒤집고, 읽기 헤드는 자구의 자화를 저항 변화로 감지한다 플래터 면마다 하나씩 있다"},{"name":"슬라이더·공기베어링면 (slider / ABS)","role":"헤드를 얹은 작은 활공체 회전하는 플래터가 만드는 기체 층 위에 나노미터 높이로 떠 표면 접촉을 막는다 밑면 형상과 내부 히터(DFH)가 부양 높이를 결정한다"},{"name":"액추에이터 암 (actuator arm / 헤드 스택 어셈블리)","role":"여러 헤드를 한 묶음으로 붙잡고 피벗을 중심으로 부채꼴로 회전하는 팔 모든 헤드가 함께 움직여 같은 실린더 위치를 가리킨다"},{"name":"보이스코일 모터 (VCM, voice coil motor)","role":"영구자석 자기장 속 코일에 전류를 흘려 액추에이터 암을 목표 트랙으로 재빠르고 정밀하게 이동시키는 구동부 전류 세기·방향으로 위치와 속도를 제어한다"},{"name":"마이크로액추에이터 (PZT microactuator)","role":"VCM의 굵은 위치 잡기를 넘어 헤드를 나노미터 단위로 미세보정하는 압전 소자 트랙이 좁아진 현대 드라이브의 2단·3단 서보 정밀도를 담당한다"},{"name":"서보 정보 (embedded servo)","role":"플래터에 방사형 쐐기(웨지)로 미리 새겨 둔 위치 기준 신호 헤드가 읽어 현재 트랙·오프셋을 실시간 피드백받는 폐루프 위치 제어의 기준점이 된다"},{"name":"로드/언로드 램프 (load/unload ramp)","role":"유휴·전원 차단 시 헤드를 플래터 바깥으로 대피시키는 경사 구조물 충격 시 헤드-표면 접촉을 막아 데이터와 헤드를 보호한다"},{"name":"프리앰프 (preamplifier)","role":"헤드가 만든 극히 미약한 읽기 신호를 헤드 근처(액추에이터 위)에서 곧바로 증폭하고, 쓰기 전류를 헤드로 보내는 칩 신호가 길게 흐르며 잡음에 묻히기 전에 처리한다"},{"name":"플렉스 케이블 (flex cable / FPC)","role":"움직이는 액추에이터 위의 헤드·프리앰프와 정지된 PCB 컨트롤러를 잇는 유연 인쇄회로 암이 왕복해도 신호·전원을 끊김 없이 전달한다"},{"name":"온보드 컨트롤러 SoC·리드 채널","role":"인터페이스 처리, LBA→물리주소 변환, 서보 제어, 리드 채널(파형→비트 복원), ECC, 캐시 관리를 총괄하는 두뇌 HDD의 펌웨어가 여기서 돈다"},{"name":"DRAM 캐시 버퍼","role":"자주 읽는 데이터의 읽기 캐시(read-ahead)와 쓰기 임시 저장(write-back) 역할 느린 기계 동작과 빠른 인터페이스 사이의 속도 차를 흡수한다"},{"name":"재순환 필터 (recirculation filter)","role":"밀폐 내부를 도는 기류에서 마모 입자·미세먼지를 걸러 헤드-플래터 사이로 끼어드는 것을 막는 내부 필터 외기를 들이는 브리더 필터와는 별개다"},{"name":"SATA·SAS/전원 커넥터","role":"데이터는 SATA(소비자)/SAS(엔터프라이즈) 신호선으로, 전력은 12 V(모터 구동)와 5 V(전자부)로 공급받는 접점(신형 SATA는 3.3 V 핀도 포함) 호스트와 물리적으로 연결되는 창구다"},{"name":"밀폐 하우징·기체(공기/헬륨)","role":"먼지를 막는 밀폐 몸체 공기 봉입 드라이브는 습기·기압 조절용 외기 브리더 필터를 두고, 대용량 드라이브는 헬륨을 채워 완전 밀봉한다(헤드가 뜨려면 내부는 진공이 아니라 기체로 채워져 있어야 한다)"}],"model":"hdd"},{"id":"spirom","name":"펌웨어 플래시","category":"저장장치","summary":"시작에 필요한 펌웨어를 보관합니다","detail":"전원을 넣은 직후, 아직 DRAM도 초기화되지 않고 OS도 없는 무(無)의 상태에서 CPU가 실행할 '맨 처음 코드(펌웨어)'를 보관하는 칩이다 CPU는 리셋되면 하드웨어로 고정된 주소(리셋 벡터)에서 명령을 가져오는데, 칩셋(PCH)/SoC가 이 주소를 SPI 플래시로 디코드해 매핑해 둔다 즉 이 칩은 저장 용량으로 승부하는 장치가 아니라 '언제나 같은 자리에서, 전원만 들어오면, 별도 초기화 없이 즉시 읽히는' 신뢰할 수 있는 시작점을 제공하는 것이 본질적 역할이다 이 플래시는 CPU뿐 아니라 관리 엔진(ME/PSP)·EC 등도 각자의 리전을 읽어 가는 공용 저장소이기도 하다 부팅이 끝나 OS가 SSD에서 올라온 뒤에는 대부분 조용히 쉬며, UEFI 설정·부트 순서·Secure Boot 키 같은 비휘발성 값을 계속 보관한다","parts":[{"name":"NOR 플래시 셀 어레이 (플로팅 게이트/차지 트랩 트랜지스터)","role":"실제 비트를 담는 심장부 각 셀이 전하의 유무로 문턱전압을 바꿔 0/1을 비휘발성으로 기억한다 NOR 배선 구조 덕분에 셀 하나(바이트)를 개별적으로 빠르게 랜덤 읽기 할 수 있어 코드 저장·XIP에 적합하다"},{"name":"행·열 디코더 + 감지 증폭기 (sense amplifier)","role":"요청된 주소의 셀을 골라내고, 셀에 흐르는 극히 작은 전류를 기준 전류와 비교해 논리 레벨(0/1)로 판독한다 랜덤 접근 읽기의 속도와 정확도를 좌우한다"},{"name":"SPI 직렬 인터페이스 로직 (명령 디코더·주소 래치·시프트 레지스터) + SFDP 테이블","role":"SCLK에 맞춰 들어오는 명령 코드와 주소를 해석하고, 읽은 데이터를 직렬 출력한다 Single/Dual/Quad(1·2·4비트) 전송 폭과 Fast Read 등 명령을 처리한다 JEDEC 표준 SFDP(직렬 플래시 파라미터 발견) 테이블을 내장해, 컨트롤러가 이 칩의 용량·지원 명령·더미 사이클 등을 자동 인식하게 한다"},{"name":"상태·설정 레지스터 (Status/Configuration Register) + OTP/보안 레지스터","role":"쓰기 활성 래치(WEL), 블록 보호 비트(BP/TB), Quad Enable, 소거/프로그램 진행 상태(Busy/WIP) 등을 담아 쓰기 보호와 동작 모드를 결정한다 별도의 OTP(1회 프로그램) 보안 레지스터 영역을 두어 고유 ID·서명 등 불변 데이터를 보관하기도 한다"},{"name":"차지 펌프 (charge pump)","role":"3.3V(또는 1.8V) 공급 전압에서 셀을 프로그램·소거하는 데 필요한 더 높은 내부 전압을 만들어 낸다 재기록을 물리적으로 가능하게 하는 부품"},{"name":"프로그램/소거 상태 머신 (내부 컨트롤러)","role":"페이지 프로그램(쓰기)과 섹터/블록 소거의 순서·타이밍·검증을 자동으로 관리한다 NOR는 비트를 1→0으로만 프로그램할 수 있어(소거가 1로 되돌림), 되돌리려면 섹터/블록 전체를 소거해야 하는데 이 로직이 그 절차를 담당한다"},{"name":"쓰기 보호 로직 + WP#/HOLD#(또는 RESET#) 핀","role":"하드웨어 핀(WP#)과 상태 레지스터의 보호 비트로 특정 영역의 무단 쓰기를 막는다 펌웨어 변조를 막는 1차 방어선이며, 메인보드/PCH의 플래시 쓰기 보호 정책과 맞물린다"},{"name":"8핀 패키지와 핀 배열 (CS#, SCLK, SI/IO0, SO/IO1, WP#/IO2, HOLD#(RESET#)/IO3, VCC, GND)","role":"SOIC/WSON 8핀 몸체로 메인보드에 실장된다 병렬 ROM 대비 핀 수가 매우 적어 작은 칩으로 만들 수 있고, Quad 모드에서는 IO0~IO3 4개 핀을 동시에 데이터 선으로 쓴다"},{"name":"(보드측) PCH/CPU의 SPI 컨트롤러 + BIOS 디코드 윈도우 + 쓰기 보호 레지스터","role":"칩 자체는 아니지만 논리적으로 한 쌍 CPU의 메모리 읽기(리셋 벡터 포함)를 SPI 트랜잭션으로 번역하고, 주소공간 상위를 플래시에 매핑한다 BIOS_CNTL(BLE/BIOSWE·SMM_BWP)·Protected Range(PRx)·FLOCKDN 같은 레지스터로 플래시 쓰기 보호를 실제로 강제하는 것도 이 컨트롤러다"},{"name":"논리적 저장 구조: Flash Descriptor · BIOS(내부에 NVRAM 변수 저장소) · ME/CSME · GbE · EC 등 리전","role":"인텔 플랫폼에서는 플래시 첫머리의 Flash Descriptor가 전체 레이아웃과 리전별 접근 권한을 정의한다 그 아래로 BIOS(UEFI 펌웨어 — UEFI 변수/부트 순서/Secure Boot 키를 담는 NVRAM 저장소는 이 BIOS 리전 내부의 펌웨어 볼륨이다), ME/CSME(관리 엔진 펌웨어), 필요시 GbE(네트워크)·EC·Platform Data 리전이 한 칩 안에 공존한다"}],"model":"spirom"},{"id":"mainboard","name":"메인보드","category":"기판·버스·전원","summary":"부품을 장착하고 신호와 전원을 이어줍니다","detail":"메인보드는 스스로 연산하지 않는다 대신 CPU·RAM·GPU·저장장치·I/O 장치가 서로 전기 신호를 주고받을 길(구리 트레이스)과 꽂을 자리(소켓·슬롯)를 제공하고, PSU의 전원을 각 부품이 요구하는 전압으로 변환해 배분한다 여기서 칩셋(Intel의 PCH, AMD의 FCH)은 USB·SATA·추가 PCIe·네트워크·오디오처럼 상대적으로 느리고 수가 많은 장치들을 한데 모아 관리하는 I/O 허브 역할을 맡아, 이들을 DMI라는 한 개의 고속 업링크로 CPU에 연결한다 과거 노스브리지가 담당하던 메모리 컨트롤러·주 PCIe·내장 그래픽은 모두 CPU 안으로 이동했기 때문에, 오늘날 메인보드 위의 대형 칩은 사실상 이 칩셋 하나뿐이다 또한 RTC 시계 유지, 기준 클럭 생성, 전원 시퀀싱, 신뢰 루트(TPM/fTPM), (노트북의) 임베디드 컨트롤러 같은 상시·관리 기능이 벌어지는 무대이기도 하다","parts":[{"name":"다층 PCB 기판 (FR-4)","role":"유리섬유·에폭시(FR-4) 절연층과 구리층을 여러 겹 쌓아 만든 판 저가형은 4층, 소비자 주류는 6~8층, 고급·오버클럭은 8~12층 이상으로, 신호층·전원 평면·접지 평면을 번갈아 배치해 모든 배선의 무대가 된다"},{"name":"구리 트레이스와 전원·접지 평면","role":"신호가 흐르는 얇은 구리 선로(트레이스, 두께 대략 35µm/1oz)와, 넓게 깔린 전원 평면·접지 평면 트레이스는 폭·간격·유전체 두께로 임피던스가 결정되고, 접지 평면은 리턴 경로와 노이즈 차폐를 제공한다 전류가 큰 전원 평면은 2oz(약 70µm) 이상을 쓰기도 한다"},{"name":"CPU 소켓 (LGA + 리텐션)","role":"CPU를 앉히는 자리 요즘 데스크톱은 LGA 방식(핀이 소켓 쪽, CPU는 평평한 접점)으로 수백~1800여 개 접점을 누른다(예: LGA1700/LGA1851) ILM(독립 로딩 메커니즘) 레버가 CPU를 균일하게 눌러 접촉을 확보한다 노트북 CPU는 BGA로 기판에 직접 납땜된다"},{"name":"DIMM 메모리 슬롯","role":"RAM 모듈(DDR5 기준 288핀 DIMM)을 꽂는 슬롯 CPU 내장 메모리 컨트롤러(IMC)에 직결되며, 보통 2~4개가 채널로 배선된다 DDR5는 한 모듈이 2×32비트 독립 서브채널로 나뉘고, 전원 조정(PMIC)이 보드가 아닌 모듈 위로 옮겨와 5V 입력에서 약 1.1V를 자체 생성한다 신호 타이밍을 맞추려 트레이스 길이를 정교하게 정합한다"},{"name":"M.2 슬롯","role":"NVMe SSD·Wi-Fi 모듈용 소형 슬롯 NVMe SSD는 주로 2280 크기의 M-키(PCIe x4, 일부 B+M키는 SATA)를 쓰고, Wi-Fi/BT 모듈은 별도의 2230 A+E 키 슬롯(CNVi 또는 PCIe x1+USB)을 쓴다 NVMe M.2는 한 개 정도가 CPU 직결, 나머지는 칩셋 경유 PCIe로 연결되는 경우가 많다"},{"name":"PCIe 확장 슬롯","role":"그래픽카드용 x16(주로 CPU 직결)과 확장 카드용 x1·x4 슬롯(주로 칩셋 경유) 물리적으로 x16 크기여도 전기적으로는 x8·x4로 배선된 경우가 있어 겉모습과 실제 레인 수가 다를 수 있다"},{"name":"칩셋(PCH) 칩 + 히트싱크","role":"USB·SATA·추가 PCIe 레인·이더넷 MAC·저속 I/O·RTC·(Intel의) 관리 엔진을 품은 대형 I/O 허브 칩 자체 다운스트림 PCIe 레인(최신 인텔 칩셋 20~28레인급)까지 제공하며 이 모두가 DMI x8를 공유한다 발열이 있어 방열판이 덮인다 사실상 오늘날 메인보드에서 CPU 외의 유일한 큰 칩이다"},{"name":"VRM (전압 조정 모듈)","role":"CPU 소켓 위·왼쪽에 늘어선 전원부 PWM 컨트롤러가 여러 '상(phase)'을 지휘하고, 각 상의 MOSFET(또는 통합 파워스테이지 DrMOS), 인덕터(초크), 캐패시터가 12V를 약 1V의 대전류(수십~수백 A) Vcore로 정밀 강압한다 방열판이 덮인다"},{"name":"전원 커넥터 (24핀 ATX, 8핀 EPS)","role":"PSU에서 오는 전원을 받는 입구 24핀 메인 커넥터가 3.3·5·12V와 대기 전원·제어 신호를, 8핀 EPS 커넥터가 CPU VRM용 12V를 집중 공급한다 고전력 보드는 EPS를 8+8(또는 8+4)로 이중 배치하기도 한다"},{"name":"SPI 플래시 롬 (UEFI/BIOS)","role":"부팅 펌웨어(UEFI)와 설정을 저장하는 작은 비휘발성 칩으로 PCH의 SPI 컨트롤러에 연결된다 전원이 켜지면 CPU가 가장 먼저 읽는 부팅의 출발점이며, 대부분의 UEFI 설정도 여기 NVRAM 영역에 저장된다"},{"name":"RTC + 32.768kHz 크리스탈 + CMOS 배터리","role":"실시간 시계(RTC)는 크리스탈로 초를 세어 날짜·시간을 유지한다 CR2032 코인 배터리(3V)가 컴퓨터 전원이 꺼져 있는 동안에도 RTC와 일부 설정 상태에 전력을 대준다"},{"name":"클럭 생성기 / 기준 크리스탈","role":"100 MHz 베이스 클럭(BCLK)과 PCIe·USB·SATA·메모리·DMI용 기준 클럭들을 생성·분배한다 최신 플랫폼은 상당 부분이 칩셋에 통합되지만, 별도 클럭 제너레이터 칩을 둔 보드도 있다"},{"name":"임베디드 컨트롤러(EC) / Super I/O","role":"노트북의 EC는 CPU와 별개로 항상 돌며 전원 시퀀싱·배터리 충전·팬·키보드 스캔·전원 버튼·절전 복귀를 관리하는 작은 마이크로컨트롤러다 데스크톱에서는 Super I/O 칩이 팬 제어·하드웨어 모니터링 등 일부를 담당한다"},{"name":"네트워크 소자 (이더넷 컨트롤러/PHY, Wi-Fi 모듈)","role":"유선 랜은 두 방식이 있다 (a) 칩셋 내장 이더넷 MAC + 외부 PHY 칩, 또는 (b) MAC+PHY를 하나로 통합한 독립 PCIe 이더넷 컨트롤러(Realtek RTL8125, Intel i225/i226 등, 대개 2.5GbE)를 PCIe 레인에 물리는 방식 Wi-Fi는 CNVi 방식으로 MAC은 칩셋에, RF 모듈은 M.2(2230 A+E키) 카드에 나뉘어 실린다"},{"name":"오디오 코덱 칩과 SATA 포트","role":"칩셋의 HD Audio(또는 최신 SoundWire) 인터페이스에 연결된 코덱 칩이 아날로그 소리(DAC/ADC)를 담당하며 후면 잭으로 연결된다 SATA 포트들은 칩셋의 SATA 컨트롤러에 물려 HDD·SATA SSD를 받는다"},{"name":"TPM / fTPM (신뢰 플랫폼 모듈)","role":"부팅 무결성 측정과 암호 키·인증서를 안전하게 보관하는 보안 루트 별도 TPM 칩(SPI/LPC 헤더에 장착)일 수도, 칩셋 ME/CPU에서 도는 펌웨어 TPM(Intel PTT / AMD fTPM)일 수도 있다 Windows 11의 TPM 2.0 요구 사항 때문에 사실상 표준 구성요소가 됐다"},{"name":"후면 I/O 패널·헤더·진단 LED","role":"USB·LAN·오디오 잭이 모인 후면 포트 패널, 팬·RGB·프론트패널 스위치용 핀 헤더, 그리고 부팅 단계 오류를 알려주는 진단 LED나 POST 코드 표시기가 기판 곳곳에 배치된다"}],"model":"mainboard"},{"id":"bus","name":"버스","category":"기판·버스·전원","summary":"장치 사이에 데이터를 옮기는 연결 체계입니다","detail":"버스와 인터커넥트는 컴퓨터 부품들 사이를 잇는 도로망이자 그 위의 교통 규칙이다 대역폭이 생명인 장치(GPU·주 NVMe SSD)는 CPU에 직결하고, 느린 다수(USB·SATA·오디오·네트워크)는 칩셋에 모아 한 가닥(DMI)으로 공유시키는 '대역폭 계층'을 설계한다 데이터는 패킷(TLP)으로 쪼개 직렬 차동 배선으로 신뢰성 있게(재전송 보장) 전달하고, CPU가 일일이 바이트를 옮기지 않도록 DMA에 전송을 위임한 뒤 완료를 인터럽트로 통보받는다 부팅 때 버스를 열거(enumeration)해 장치마다 정체를 파악하고 주소를 배정하는 것부터가 이 계층의 일이며, 최근에는 같은 PCIe 전기 배선 위에 캐시 일관성 프로토콜(CXL)을 얹어 메모리 확장·가속기 연결까지 확장되고 있다 사실상 CAwiki의 모든 시나리오에서 '데이터가 이동하는 구간'은 전부 여기서 벌어진다","parts":[{"name":"루트 컴플렉스(Root Complex)","role":"CPU와 PCIe 세계를 잇는 관문 CPU의 메모리·I/O 요청을 PCIe 트랜잭션(TLP)으로 바꿔 아래 장치들로 내려보내고, 열거·주소 매핑의 출발점이 된다 현대에는 CPU 다이 안에 통합되어 있으며, CXL 링크의 호스트 측 앵커(루트 포트) 역할도 겸한다"},{"name":"PCIe 레인과 차동 배선쌍(SerDes PHY)","role":"실제 데이터가 흐르는 길 레인 1개는 송신 1쌍·수신 1쌍의 차동 배선으로 이뤄지며, PHY의 직렬화기/역직렬화기(SerDes)가 CPU 내부의 병렬 비트를 직렬 신호로 바꿔 보내고 받는 쪽에서 되돌린다 x1·x4·x8·x16으로 묶어 폭을 키우며(bifurcation으로 x16을 x8+x8 등으로 쪼갤 수도 있다)"},{"name":"PCIe 스위치·브리지(Switch/Bridge)","role":"레인을 분기해 여러 장치를 붙인다 상위 버스에서 온 패킷을, 목적지 주소가 속한 하위 버스로만 골라 전달한다(포워딩) 열거 때 각 브리지의 하위 버스 번호와 주소 범위가 프로그래밍된다"},{"name":"칩셋(PCH / 사우스브리지)","role":"USB·SATA·유선 네트워크·오디오·저속 PCIe 등 느린 다수의 I/O를 한데 모으는 허브 여기 붙은 장치들은 CPU로 올라가는 상향 링크(DMI 등)의 대역폭을 나눠 쓴다 과거 노스브리지의 메모리·그래픽 기능은 CPU로 흡수되었다"},{"name":"DMI 링크(Direct Media Interface)","role":"Intel에서 CPU와 칩셋을 잇는 전용 상향 링크 사실상 PCIe와 같은 방식이며(고급 칩셋은 DMI 4.0 = PCIe 4.0 x8 상당, 보급형은 x4), 칩셋 아래 모든 장치의 트래픽이 이 좁은 병목을 통과해 CPU로 간다 (AMD는 별도 이름 대신 PCIe 4.0 x4 링크 자체로 칩셋을 연결한다.)"},{"name":"메모리 컨트롤러(IMC)와 메모리 버스","role":"CPU 다이 안에 통합된 컨트롤러가 DDR/LPDDR RAM을 CPU에 직결한다 PCIe·DMI와 별개인 최고 대역폭 경로로, DMA 전송의 반대편 종착지가 대개 이 RAM이다 최근에는 CXL로 붙는 메모리 확장 계층이 이 로컬 RAM 바깥의 추가 메모리로 쓰이기도 한다"},{"name":"DMA 엔진 / 버스 마스터","role":"CPU 개입 없이 메모리와 장치 사이 데이터를 실제로 나르는 일꾼 현대 장치(NVMe·NIC·GPU)는 저마다 이 엔진을 내장한 '버스 마스터'로, 디스크립터를 읽어 스스로 전송을 수행하고 흩어진 페이지(scatter-gather)까지 처리한다"},{"name":"IOMMU (입출력 메모리 관리 장치)","role":"장치가 DMA로 대는 주소를 검사·번역하는 관문(Intel VT-d, AMD-Vi) 각 장치를 허가된 메모리 영역에만 가두어 오작동·악성 장치의 임의 메모리 접근을 막고, 인터럽트 재매핑과 가상화(장치 통과, SR-IOV)를 돕는다"},{"name":"인터럽트 컨트롤러(로컬 APIC + I/O APIC)","role":"장치가 보낸 '작업 완료' 신호를 어느 코어에 전달할지 라우팅한다 레거시 와이어 인터럽트는 I/O APIC가 받아 각 코어의 로컬 APIC로 분배하고, 현대 MSI/MSI-X는 로컬 APIC로 직접 배달된다 로컬 APIC는 코어의 타이머와 코어 간 신호(IPI)도 담당하며, 코어가 많으면 x2APIC 모드를 쓴다"},{"name":"MSI / MSI-X 메커니즘","role":"전용 인터럽트 전선 없이, 약속된 메모리 주소에 값을 쓰는 것만으로 인터럽트를 표현하는 방식 MSI는 함수당 최대 32벡터, MSI-X는 최대 2048벡터를 지원해, 다중 큐 장치(NVMe·고속 NIC)가 큐마다 다른 코어를 깨울 수 있게 한다"},{"name":"설정 공간(Configuration Space)과 BAR","role":"각 PCIe 기능이 가진 표준 레지스터 묶음 Vendor/Device ID·Class Code로 정체를 알리고, BAR(Base Address Register)로 필요한 주소 공간의 크기·종류를 선언한다 PCI 256바이트/PCIe 확장 4KB이며, 열거와 주소 매핑이 모두 이 공간을 (ECAM MMIO로) 읽고 쓰며 이뤄진다"},{"name":"호스트 컨트롤러(xHCI·AHCI 등)와 장치 인터페이스(NVMe)","role":"특정 버스 표준을 관장하는 컨트롤러 xHCI는 USB 3.x/2.0 장치를, AHCI는 SATA 장치를 NCQ(명령 큐잉)로 다룬다 반면 NVMe는 별도 호스트 컨트롤러를 경유하지 않고 PCIe에 직결된 SSD 자체의 레지스터·명령셋 인터페이스로, OS 드라이버가 이들을 통해 주변기기와 대화한다"},{"name":"온다이/패키지·소켓 간 인터커넥트(링·메시·Infinity Fabric·UPI)","role":"칩 내부에서 코어·캐시·메모리 컨트롤러·PCIe 컨트롤러를 잇고 캐시 일관성을 유지하는 그물망 Intel의 링/메시, AMD의 Infinity Fabric이 대표적이며, 칩렛(여러 다이)을 한 패키지로 묶는 접착제이자, 소켓 간에는 Intel UPI·AMD xGMI로 확장돼 멀티소켓 서버의 NUMA 도메인을 잇는다"},{"name":"코히런트 확장 링크(CXL)","role":"PCIe 5.0/6.0과 같은 전기 PHY 위에서 링크 트레이닝 때 협상되는 캐시 일관성 프로토콜(CXL.io/.cache/.mem) CPU와 가속기·메모리 확장 장치가 서로의 메모리를 일관성 있게 공유하게 해, 메모리 풀링·용량 확장·가속기 결합을 가능케 한다(주로 서버/AI) PCIe와 배선을 공유하지만 프로토콜 계층이 다르다"},{"name":"레퍼런스 클럭 / 클럭 복원(CDR)","role":"링크 양쪽이 대략 같은 박자를 맞추도록 기준 클럭(대개 100MHz)을 공급한다 실제 비트 타이밍은 데이터에 실린 임베디드 클럭을 수신부가 복원(CDR)해 맞춘다 양쪽이 같은 기준 클럭을 쓰면 공통 클럭, 각자 다른 클럭에 독립 스펙트럼 확산을 쓰면 SRIS 구성이며, 스펙트럼 확산(SSC)으로 전자파 간섭(EMI)을 줄인다"}],"model":"bus"},{"id":"power","name":"전원 공급","category":"기판·버스·전원","summary":"부품이 동작할 전력을 공급합니다","detail":"PSU(파워서플라이)는 콘센트의 교류(국내 표준 220V·60Hz, 지역에 따라 100~120V·50/60Hz)를 +12V·+5V·+3.3V 직류로 변환해 시스템 전체에 공급하고, VRM(전압 조정 모듈)은 그 12V를 CPU·GPU가 요구하는 약 1V(부하·전력상태에 따라 대략 0.7~1.4V) 수준으로 다시 낮춰 상(phase)당 초당 수십만~수백만 번 스위칭하며 고부하 시 수백 암페어를 안정적으로 흘린다 노트북에서는 리튬이온 배터리와 충전 회로·PMIC(전력관리 IC)가 콘센트 없이도 같은 일을 하며, 부하에 따라 전압과 클럭을 실시간으로 조절해 에너지를 아낀다 전원이 규격 범위 안에서 안정돼야만 Power Good 신호가 떠서 CPU의 리셋이 풀리고 비로소 컴퓨터가 깨어난다 즉 전원부는 모든 연산의 전제 조건이며, 성능·안정성·전력효율을 동시에 좌우하는 토대다","parts":[{"name":"EMI/라인 필터 (X·Y 커패시터 + 공통모드 초크)","role":"PSU가 만드는 고주파 스위칭 노이즈가 전력망으로 새는 것과 외부 서지가 들어오는 것을 양방향으로 차단한다"},{"name":"NTC 서미스터 / 돌입전류 제한","role":"전원을 켜는 순간 벌크 커패시터로 몰리는 돌입 전류를 억제해 퓨즈 단선·부품 손상을 막는다"},{"name":"브리지 정류기 (다이오드 4개)","role":"교류의 음의 반주기를 뒤집어 전류가 한 방향으로만 흐르는 맥동 직류로 바꾼다(전파정류)"},{"name":"벌크 커패시터 (고압 대용량)","role":"정류된 맥동 DC의 골을 메워 매끈한 고압 DC로 평활하고, 순간 정전(AC 소실) 시 약 16~20ms 이상 출력을 유지한다(홀드업 타임, ATX 규격 최소 약 16ms)"},{"name":"능동 PFC 회로 (부스트 컨버터 + PFC 초크)","role":"입력 전류 파형을 전압 파형에 맞춰 역률을 약 0.99로 올리고, DC 버스를 대략 380~400V로 승압한다"},{"name":"1차측 스위칭 MOSFET","role":"고압 DC를 수십~수백 kHz로 잘게 끊어(스위칭) 변압기에 넣는다 PSU의 핵심 능동소자"},{"name":"메인 스위칭 트랜스포머","role":"전압을 크게 낮추면서 위험한 1차측과 안전한 2차측을 전기적으로 절연한다"},{"name":"2차측 정류기 / 동기정류 MOSFET + 출력 필터","role":"변압기 2차 출력을 다시 정류·평활해 깨끗한 저압 DC 레일을 만든다"},{"name":"피드백 절연 (옵토커플러 + TL431 기준전압)","role":"2차측 출력 전압을 감지해 절연 장벽을 넘어 1차측 컨트롤러로 전달, 부하가 변해도 출력을 규격 안에 유지하게 한다"},{"name":"DC-DC 컨버터 모듈","role":"주 레일 12V에서 +5V·+3.3V를 파생시킨다(현대적 DC-DC 방식)"},{"name":"5VSB 대기 컨버터 (소형 플라이백)","role":"콘센트에 꽂혀 있는 한 항상 켜져 전원 버튼·대기 회로·Wake-on-LAN에 전기를 공급한다"},{"name":"PWM/공진(LLC) 컨트롤러 IC","role":"1차측 스위치의 켜고 끄는 타이밍·주파수를 제어하고 피드백으로 전압을 안정화한다"},{"name":"보호회로 (OCP/OVP/UVP/OTP/OPP/SCP)","role":"과전류·과전압·저전압·과열·과전력·단락을 감지해 즉시 출력을 차단, 부품과 사람을 보호한다"},{"name":"전원 커넥터군 (ATX 24핀 · EPS 8핀 · PCIe/12VHPWR)","role":"메인보드·CPU·GPU 등 각 소비처에 정해진 레일을 배분한다 Power Good·PS_ON# 신호선도 여기 포함"},{"name":"냉각 팬 + 온도센서","role":"변환 과정에서 손실로 발생한 열을 밖으로 배출하고, 온도에 따라 팬 속도를 조절한다(저부하 시 정지하는 세미팬리스 설계도 있음)"},{"name":"VRM PWM 컨트롤러","role":"CPU/GPU의 VID(SVID) 요청을 받아 여러 상의 스위칭을 위상차를 두고 지휘하고, 부하에 맞춰 상을 켜고 끈다"},{"name":"하이/로우사이드 MOSFET (또는 DrMOS·통합 파워스테이지)","role":"VRM 각 상에서 12V를 고속으로 스위칭해 강압하는 실제 전력 소자"},{"name":"초크 (파워 인덕터)","role":"VRM 각 상에서 스위칭 에너지를 저장·방출하며 출력 전류를 매끈하게 평활한다"},{"name":"출력 커패시터 (MLCC/폴리머)","role":"Vcore의 리플과 순간 부하 변동을 흡수해 CPU에 안정적인 전압을 공급한다"},{"name":"리튬이온/리튬폴리머 셀 (노트북)","role":"화학 에너지 형태로 전기를 저장한다 직렬로 전압을, 병렬로 용량을 키운다(예: 3S2P)"},{"name":"BMS (배터리 관리 시스템)","role":"셀 간 전압을 맞추고(밸런싱), 과충·과방전·과열·과전류를 막으며, 쿨롱 카운팅으로 잔량(%)을 계산한다"},{"name":"충전 IC","role":"어댑터 전력을 받아 CC-CV(정전류→정전압) 방식으로 셀을 안전하게 충전한다"},{"name":"PMIC (전력관리 IC)","role":"하나의 입력에서 SoC의 여러 전압 도메인(코어·메모리·I/O 등)을 만들어 분배하고 DVFS로 실시간 조절한다"},{"name":"입력 퓨즈 (Fuse)","role":"PSU 입력단의 최종 안전장치 내부 소자 단락 등 능동 보호회로로도 막지 못하는 치명적 과전류가 발생하면 스스로 녹아 끊겨 회로를 물리적으로 차단, 화재·감전과 전력망으로의 사고 확산을 막는다 돌입전류를 억제하는 NTC 서미스터, 이상 시 정상적으로 셧다운하는 능동 보호회로(OCP/SCP 등)와 달리, 한 번 끊기면 교체해야 하는 일회성·비복귀형 차단 소자라는 점에서 별개의 핵심 부품이다"}],"model":"power"},{"id":"cooling","name":"냉각","category":"기판·버스·전원","summary":"발생한 열을 밖으로 옮깁니다","detail":"CPU·GPU는 소비한 전력의 사실상 전부(신호로 빠져나가는 극소량을 빼면)를 열로 바꾼다 냉각은 이 열을 다이(die)에서 걷어내 최종적으로 주변 공기로 방출함으로써, 실리콘의 접합부 온도(junction temperature)를 안전 한계(Tjmax) 아래로 유지하는 역할을 한다 냉각기는 다이 온도를 무냉각 대비 크게 낮추지만, 냉매 압축·펠티어 같은 특수 방식을 빼면 결코 주변 공기(상온) 아래로는 내릴 수 없다 — 온도를 '만드는' 게 아니라 열을 '옮길' 뿐이다 온도를 통제하지 못하면 트랜지스터 누설전류가 늘어 더 뜨거워지는 악순환, 성능을 스스로 깎는 스로틀링, 심하면 소자 손상이 온다 즉 냉각은 칩의 '지속 성능'과 '수명'을 결정하는 인프라이며, 전원부(VRM)와 짝을 이루는 '기판·전원' 계열 하드웨어다","parts":[{"name":"열원 — 다이/트랜지스터","role":"실제 발열이 일어나는 실리콘 스위칭 손실과 누설전류로 좁은 면적에 높은 열유속을 만든다 냉각의 출발점이자 보호 대상"},{"name":"IHS (통합 히트스프레더, 뚜껑)","role":"데스크톱 CPU 다이 위에 붙은 금속 뚜껑 작은 다이의 열을 조금 넓혀 받고 물리적으로 다이를 보호한다 다이↔IHS 사이엔 내부 TIM(고급은 인듐 솔더 STIM, 저가는 페이스트)이 들어간다 노트북 CPU·모바일 AP·대다수 GPU 다이엔 IHS가 없어 방열판이 다이에 직접 닿는다"},{"name":"서멀 인터페이스 재료 — 페이스트(외부 TIM)","role":"IHS와 히트싱크 베이스 사이의 미세 공극을 금속·세라믹 입자로 메워 공기를 몰아낸다 얇고 균일해야 하며, 금속 밀착이 목적이지 그 자체가 우수한 도체는 아니다"},{"name":"서멀 패드","role":"높이 차가 있는 부품(VRM, VRAM, M.2 SSD 등)과 방열판 사이를 메우는 고무질 패드 다양한 두께의 틈을 안정적으로 채우지만 열성능은 페이스트보다 낮은 편"},{"name":"리퀴드메탈 TIM","role":"갈륨 합금 기반의 초고성능 인터페이스 열전도율이 페이스트보다 훨씬 높지만 전기 전도성이 있어 단락 위험이 있고 알루미늄을 부식(아말감화)시켜 사용처가 제한된다(주로 뚜껑 벗긴 다이·다이렉트 다이·일부 노트북)"},{"name":"마운팅/리텐션 (백플레이트·브래킷·스프링 스크류)","role":"쿨러를 다이 위에 일정하고 고른 압력으로 눌러 붙이는 장치 접촉 열저항과 TIM 두께를 좌우하는 숨은 핵심으로, 압력이 낮거나 한쪽으로 치우치면 아무리 좋은 쿨러·TIM도 성능이 무너진다"},{"name":"히트싱크 베이스 / 콜드플레이트","role":"IHS(또는 다이)에서 열을 받아 확산시키는 금속 판(주로 구리) 히트파이프·핀·워터블록의 뿌리 역할"},{"name":"핀(fin) 스택","role":"얇은 금속 판을 촘촘히 세워 방열 표면적을 극대화한다 공기와 닿는 면적이 곧 방열 능력이며, 무게·비용 때문에 주로 알루미늄을 쓴다"},{"name":"히트파이프","role":"밀봉·감압된 구리관 안 작동유체의 증발-응축(상변화)으로 열을 베이스에서 핀 끝까지 초고속으로 이송한다 내벽의 윅(모세관 구조)이 액체를 되돌린다 설치 방향(중력)에 성능이 다소 민감하다"},{"name":"베이퍼챔버","role":"히트파이프를 넓은 평판으로 만든 2차원 방열판 작은 다이의 높은 열유속을 넓은 면적으로 균일하게 펴는 데 유리해 고급 GPU·노트북·스마트폰에 쓰인다"},{"name":"공랭 팬","role":"핀 사이로 공기를 강제 순환시켜 대류 열전달을 유지한다 정압형(라디에이터·촘촘한 핀용)과 풍량형(케이스 환기용)으로 성격이 갈린다 대개 4핀 PWM으로 속도를 제어한다"},{"name":"케이스 흡·배기 팬 / 에어플로 경로","role":"차가운 외기를 방열판으로 들이고 데워진 공기를 케이스 밖으로 뺀다 흡기·배기 균형(양압/음압)과 통풍 경로가 방열판이 실제로 마시는 공기 온도를 결정한다"},{"name":"워터블록 (수랭)","role":"CPU/GPU 위에 얹는 수랭용 블록 내부 미세 채널·핀에 냉각수를 흘려 다이 열을 받아낸다 히트싱크 베이스에 해당하는 부품"},{"name":"펌프 (수랭)","role":"냉각수를 블록→라디에이터→다시 블록으로 순환시키는 심장 유량이 부족하면 열이 실려 나가지 못한다 AIO(일체형)는 펌프가 블록에 통합된 경우가 많다"},{"name":"라디에이터 (수랭)","role":"데워진 냉각수의 열을 핀+팬으로 공기에 넘기는 열교환기 120·240·280·360·420mm 등 크기가 방열 용량을 좌우한다 결국 수랭도 마지막엔 공기로 버린다"},{"name":"냉각수 / 작동유체","role":"블록의 열을 라디에이터로 실어 나르는 매개 물 기반에 부식 방지제와, 미생물 억제를 위한 살균제(은 이온 등)를 섞으며, 저온 환경용엔 글리콜(동결방지)을 더한다 히트파이프의 작동유체(대개 순수한 물, 감압 상태)와는 역할이 다르다"},{"name":"온도 센서 (DTS/열 다이오드)","role":"다이 여러 지점의 접합부 온도를 실시간 디지털로 읽어 팬 제어와 스로틀링 판단의 근거를 제공한다"},{"name":"팬 컨트롤러 / PWM 회로","role":"센서 온도를 팬커브에 대입해 PWM 신호(듀티비)로 팬·펌프 속도를 조절하고, tach 신호로 실제 RPM을 되읽는다 소음과 냉각의 균형을 자동으로 맞춘다"}],"model":"cooling"},{"id":"display","name":"모니터","category":"입출력","summary":"계산한 결과를 눈에 보이는 빛으로 바꿉니다","detail":"컴퓨터가 계산한 결과가 사람 눈에 도달하는 마지막 관문이다 GPU의 디스플레이 엔진이 프레임버퍼를 좌상단부터 한 줄씩 읽어(스캔아웃) 내보내는 디지털 픽셀 스트림을 받아, 사람이 볼 수 있는 빛으로 변환한다 화면의 각 픽셀은 R·G·B 서브픽셀로 나뉘고, 이 세 밝기의 혼합으로 모든 색을 만든다 CPU·GPU·메모리가 아무리 빨라도 이 장치가 없으면 결과를 눈으로 확인할 수 없는, 인간-기계 인터페이스의 '눈' 역할을 한다","parts":[{"name":"패널(디스플레이 패널)","role":"실제로 빛을 내는 화면 수백만 화소가 행·열 격자로 배열된 유리 기판 크게 LCD 방식과 OLED 방식으로 나뉜다"},{"name":"편광판(폴라라이저) 2장","role":"LCD에서 백라이트 앞뒤로 직교하게 배치돼, 액정이 빛의 편광 방향을 얼마나 돌렸는지에 따라 통과 광량을 결정한다 액정이 '빛의 밸브'로 작동하게 하는 전제 부품"},{"name":"액정층(리퀴드 크리스털)","role":"LCD의 핵심 전압에 따라 분자 배열이 회전하며 통과하는 빛의 편광을 비틀어 밝기를 조절한다 스스로 빛나지 않고 백라이트 빛을 여닫을 뿐이다 TN·IPS·VA는 이 액정을 배열·구동하는 방식의 차이다"},{"name":"컬러필터(RGB)","role":"LCD에서 백색광을 화소마다 빨강·초록·파랑 셀로판처럼 걸러 색을 만든다 세 서브픽셀의 투과량 조합이 최종 색이 된다"},{"name":"TFT 어레이(박막트랜지스터 백플레인)","role":"화소마다 하나씩 놓인 초소형 스위치 트랜지스터의 격자 행·열 주소로 특정 화소만 골라 값을 쓰고 유지시키는 액티브 매트릭스의 뼈대다 LCD는 화소당 대략 1T1C, OLED는 전류 구동을 위해 2T1C 이상으로 회로가 더 복잡하다"},{"name":"백라이트 유닛(LED + 도광판/확산판)","role":"LCD의 광원 화면 가장자리에 LED를 둔 엣지형과 뒤 전면에 깔린 직하형이 있고, 도광판·확산판이 빛을 화면 전체로 고르게 편다 OLED에는 없다"},{"name":"로컬디밍 / 미니LED 백라이트","role":"직하형 백라이트를 수백~수천 개의 존으로 나눠, 어두운 영역의 LED를 따로 낮춰 명암비를 끌어올린다 미니LED는 훨씬 작은 LED를 수천~수만 개 촘촘히 박아 존을 잘게 나눈 것"},{"name":"OLED 유기 발광층(대안 방식)","role":"백라이트·액정·컬러필터 없이 각 서브픽셀의 유기물이 전류로 자체 발광한다 화소 단위로 완전히 끌 수 있어 명암비가 사실상 무한대 WOLED(백색+컬러필터)·QD-OLED(청색+퀀텀닷) 등 변형이 있다"},{"name":"타이밍 컨트롤러(TCON)","role":"들어온 픽셀 데이터를 패널 구동 타이밍으로 재편성하고, 게이트·소스 드라이버에게 '언제 어느 행을, 어떤 열 값으로' 쓸지 지시하는 지휘자"},{"name":"소스 드라이버(데이터/컬럼 드라이버) IC","role":"선택된 행의 각 서브픽셀 열에 목표 밝기에 해당하는 데이터 전압을 실어 주는 IC(LCD는 그 전압을 화소 축전기에 저장, OLED는 화소 구동 TFT가 전류로 변환) D/A 변환 정밀도가 계조(밝기 단계)의 정밀도를 좌우한다"},{"name":"게이트 드라이버(스캔/로우 드라이버) IC","role":"TFT 격자에서 한 번에 한 행씩 순서대로 켜서 '지금 이 줄을 쓸 차례'라고 주소를 찍는다 위에서 아래로 화면을 훑는 스캔의 주체"},{"name":"스케일러 / 메인보드 SoC","role":"입력 해상도를 패널 네이티브 해상도로 변환하고, 여러 입력 소스 전환·OSD 메뉴·색 보정·오버드라이브 등 프레임 처리를 담당하는 모니터의 두뇌 처리 시간이 입력지연에 크게 반영된다"},{"name":"입력 인터페이스(포트 + 리시버 PHY)","role":"HDMI·DisplayPort·USB-C 포트와 링크를 복원하는 수신 회로 EDID/DDC로 자신의 지원 해상도·주사율을 컴퓨터에 알려 협상한다"},{"name":"전원부·구동 회로(PSU/드라이버 보드)","role":"교류 전원을 패널·백라이트·로직용 여러 전압으로 변환해 공급한다 백라이트 밝기 제어(PWM/DC 디밍)도 여기서 이뤄진다"},{"name":"내부 프레임/라인 버퍼 메모리","role":"오버드라이브(이전·현재 프레임 비교), 스케일링, 프레임 처리, VRR 보정을 위해 픽셀을 잠시 저장하는 모니터 내부 메모리 이 버퍼링이 입력지연에 더해진다"},{"name":"광학 필름·표면 코팅","role":"편광·위상차·확산·프리즘 등 광학 필름과, 화면 표면의 안티글레어(무광)/글로시(유광) 코팅 시야각·반사·선명도 인상을 좌우한다"},{"name":"OSD 컨트롤·MCU·버튼/조이스틱","role":"밝기·명암·입력 소스·게임 모드 등 설정을 다루는 마이크로컨트롤러와 물리 조작부 사용자와 모니터 펌웨어의 접점"}],"model":"display"},{"id":"input","name":"키보드·입력","category":"입출력","summary":"사람의 동작을 디지털 입력으로 바꿉니다","detail":"입력장치는 인간과 컴퓨터 사이의 '경계면'으로, 아날로그 세계의 물리량(압력, 위치 변화, 정전용량, 빛의 반사, 자기장)을 CPU가 처리할 수 있는 이산적 디지털 값으로 변환한다 각 장치 안에는 자체 마이크로컨트롤러(MCU)가 들어 있어 센서를 스캔·샘플링하고 노이즈를 걸러낸 뒤 USB HID 같은 표준 프로토콜로 포장해 호스트로 보낸다 덕분에 운영체제는 키보드·마우스·게임패드 제조사가 달라도 동일한 방식으로 입력을 해석한다 컴퓨터가 하는 거의 모든 작업(부팅 시 키 입력, 검색어 타이핑, 게임 조작, 저장 단축키)은 입력장치가 만든 이벤트에서 시작된다 참고로 이 문서는 사람이 조작해 이산 이벤트를 만드는 HID 계열(키보드·마우스·터치·게임패드·지문)을 중심으로 다루며, 마이크·카메라·스캐너 같은 장치도 넓은 의미의 입력장치이지만 이벤트가 아닌 오디오/영상 스트림 파이프라인을 쓰는 별개 경로다","parts":[{"name":"키 스위치 (기계식/멤브레인/광학)","role":"키보드에서 실제로 눌림을 감지하는 접점 기계식은 스프링과 금속 접점을 쓰는 개별 스위치(예: 청/적/갈축)로 명확한 촉감과 긴 수명(5천만~1억 회)을 주고, 멤브레인/러버돔은 고무 돔이 눌리며 두 필름의 도전층을 맞닿게 해 값싸고 조용하지만 촉감이 뭉툭하다 광학식은 빛 차단으로 눌림을 감지해 접점 바운스가 없다"},{"name":"키 매트릭스 회로 (행·열 격자 + 다이오드)","role":"모든 키를 개별 배선하지 않고 행렬로 엮어, 적은 핀 수로 많은 키를 읽게 한다 컨트롤러가 행에 전압을 걸고 열을 읽어 교차점을 특정한다 각 키에 다이오드를 달아 전류 역류를 막으면 여러 키 동시 입력 시 유령 입력(ghosting)을 방지하고 N키 롤오버(NKRO)를 구현한다"},{"name":"장치 마이크로컨트롤러 (MCU) / 컨트롤러 IC","role":"입력장치의 두뇌 센서 스캔, 디바운스, 좌표·이동량 계산, HID 리포트 생성, USB/무선 통신을 담당하는 소형 프로세서 키보드·마우스·게임패드마다 각자의 펌웨어가 올라간 전용 칩이 들어 있다"},{"name":"광/레이저 이미지 센서 + DSP (마우스)","role":"LED(주로 적색) 또는 IR 레이저로 바닥을 비추고, 작은 CMOS 이미지 센서 배열이 표면 무늬를 초당 수천~수만 프레임으로 촬영한다 내장 DSP가 프레임 간 무늬 이동을 상관 분석해 이동 방향·거리(Δx, Δy)를 산출한다"},{"name":"정전용량 전극 격자 + 터치 컨트롤러 (터치스크린)","role":"투명 전도막(ITO 등)으로 만든 가로(구동)·세로(감지) 전극이 격자를 이룬다 손가락이 닿으면 해당 교차점의 상호 정전용량이 변하고, 터치 컨트롤러가 격자를 스캔해 변화의 무게중심으로 (x, y) 좌표와 다중 터치를 계산한다"},{"name":"능동형 스타일러스 / 디지타이저","role":"터치 계열의 정밀 입력 부품 전자기 유도(EMR) 방식 디지타이저나 정전 결합식 능동 펜은 펜촉 위치뿐 아니라 필압(수백~수천 단계)과 기울기까지 읽어, 손가락 터치보다 정밀한 필기·드로잉 좌표를 만든다"},{"name":"아날로그 스틱 (포텐셔미터/홀센서) + ADC","role":"게임패드의 스틱은 X·Y 두 축의 저항(포텐셔미터) 또는 홀 효과 센서로 기울기를 전압으로 바꾸고, ADC가 이를 디지털 값으로 읽어 방향·세기를 연속적으로 표현한다 중심 근처 미세 떨림을 무시하는 데드존 처리가 들어간다"},{"name":"햅틱 액추에이터 (진동 모터)","role":"역방향 피드백 담당 편심 회전 모터(ERM)나 선형 공진 액추에이터(LRA), 최신 컨트롤러의 보이스코일형 정밀 햅틱이 호스트 명령에 따라 진동을 만들어 타격감·질감을 전달한다"},{"name":"지문 센서 어레이 (정전/광학/초음파)","role":"손가락 표면의 융선(마루)과 골을 읽는다 정전식은 미세 정전판 배열이 융선/골의 거리 차로 생기는 정전용량 차를 이미지화하고, 광학식은 빛 반사로 지문 이미지를 찍으며, 초음파식은 음파가 융선/골에서 반사되는 시간·강도로 표면의 3D 요철을 재구성한다(화면 아래 배치·젖은 손가락에 유리) 원본 대신 특징점(minutiae) 템플릿을 추출해 보안 영역에 저장한다"},{"name":"USB/무선 인터페이스 회로","role":"장치와 호스트를 잇는 통로 유선은 USB 트랜시버가 인터럽트 전송으로 리포트를 주고받고, 무선은 2.4 GHz 전용 동글이나 Bluetooth 무선 모듈이 같은 HID 데이터를 무선으로 실어 나른다"},{"name":"펌웨어 / HID 리포트 디스크립터","role":"MCU 안의 소프트웨어와, 이 장치가 '어떤 형식의 데이터를 보내는지' 호스트에 알려주는 자기소개서 디스크립터 덕분에 별도 드라이버 없이도 OS가 장치의 버튼·축·키 배치를 이해한다"},{"name":"인코더 / 스크롤 휠 (마우스)","role":"휠 회전을 광학 또는 기계식 인코더로 감지해 스크롤 스텝(노치) 또는 연속 스크롤 값으로 변환한다 클릭 버튼은 마이크로 스위치(택트 스위치)로 눌림을 감지한다"}],"model":"input"},{"id":"audio","name":"오디오","category":"입출력","summary":"숫자와 실제 소리를 서로 바꿉니다","detail":"오디오 서브시스템은 컴퓨터의 세계(0과 1의 숫자)와 사람의 세계(귀로 듣는 공기 진동) 사이를 잇는 양방향 번역기다 재생 방향에서는 메모리에 있는 PCM 샘플을 DAC로 아날로그 전압으로 되돌리고, 파워 앰프로 세기를 키워 스피커·이어폰의 진동판을 흔든다 녹음 방향에서는 마이크가 잡은 미세한 전압을 프리앰프로 키우고 ADC로 다시 숫자로 만든다 CPU·GPU·DSP가 '무엇을 들려줄지'를 계산한다면, 이 서브시스템은 그 결과를 실제로 귀에 도달시키거나 사람의 목소리를 시스템 안으로 들여보내는 마지막·첫 관문이다 순수 디지털 파트(버퍼·DMA·필터·변조)와, 잡음·간섭에 민감한 아날로그 파트(변환·증폭·트랜스듀서)가 한 경로 안에 공존하는 점이 이 서브시스템의 특징이다","parts":[{"name":"오디오 코덱 칩 (Audio Codec IC, 예: Realtek ALC·Cirrus Logic·ESS Sabre·AKM)","role":"DAC·ADC·마이크 프리앰프·헤드폰 앰프·믹서·디지털 인터페이스를 하나로 묶은 통합 칩 메인보드·폰의 '소리 담당' 핵심으로, PCM을 아날로그로 또 그 반대로 변환한다 (파일 압축 포맷인 MP3·AAC '코덱'과는 이름만 같고 다른 것.)"},{"name":"DAC (Digital-to-Analog Converter, 디지털→아날로그 변환기)","role":"PCM 숫자를 아날로그 전압 파형으로 되돌린다 대부분 오버샘플링 디지털 필터 + 델타시그마 변조기(다중비트가 흔함) + 아날로그 재구성 필터로 구성된다 (고급기는 R-2R 저항 사다리 방식도 있음.)"},{"name":"ADC (Analog-to-Digital Converter, 아날로그→디지털 변환기)","role":"마이크·라인 입력의 아날로그 전압을 안티에일리어싱 필터로 거른 뒤 표본화·양자화해 PCM 숫자로 만든다 오디오에서는 주로 델타시그마 ADC를 쓴다"},{"name":"마이크 프리앰프 / PGA (Programmable Gain Amplifier)","role":"마이크가 만든 아주 작은 신호를 ADC가 다룰 수 있는 크기로 키우는 가변이득 증폭단 이득이 너무 크면 클리핑, 너무 작으면 잡음에 묻힌다"},{"name":"헤드폰/라인 앰프 + 출력 잭 (콤보 TRRS·잭 감지)","role":"코덱 출력을 이어폰(수십 Ω)이나 라인 레벨로 내보내는 소형 증폭단과, 그 신호가 나가는 아날로그 잭 임피던스가 높은 헤드폰을 충분히 울리려면 이 단의 구동력이 중요하다 콤보(TRRS) 잭은 헤드폰+마이크를 겸하고, 잭 감지(jack detection)로 삽입 여부·타입을 인식해 스피커↔이어폰 경로를 자동 전환한다"},{"name":"파워 앰프 (Class-D 스위칭 앰프 / 스마트 앰프)","role":"스피커를 실제로 구동할 만큼 전류를 키운다 PWM 변조기 + 출력 MOSFET(하프·풀 브리지) + LC 출력 필터로 이뤄지며, 효율이 높아 모바일·소형 스피커에 표준으로 쓰인다 스마트 앰프는 IV(전류·전압) 피드백으로 코일 온도·변위를 추정해 스피커를 보호하면서 음량·저음을 끌어올린다"},{"name":"크로스오버 네트워크 (Crossover)","role":"멀티웨이 스피커에서 저음은 우퍼, 고음은 트위터로 주파수 대역을 나눠 보내는 필터 회로 코일·콘덴서로 만든 수동형과, 앰프 앞에서 DSP·능동 필터로 나누는 능동형이 있다"},{"name":"오디오 클럭 / PLL (수정 발진자 + 위상동기루프)","role":"MCLK(마스터)·BCLK(비트)·LRCLK/워드클럭 등 변환 타이밍을 만든다 클럭이 흔들리면(지터) 표본 시점이 어긋나 음질이 나빠진다 44.1 kHz 계열(22.5792 MHz)과 48 kHz 계열(24.576 MHz)을 위해 보통 두 종류의 기준 클럭을 둔다"},{"name":"디지털 오디오 인터페이스 (I2S / PDM / SoundWire / HD Audio / USB Audio)","role":"코덱과 CPU·SoC(또는 외장 장치) 사이로 오디오 데이터를 나르는 직렬 버스 I2S는 재생용 다중비트 스트림, PDM(Pulse Density Modulation)은 MEMS 마이크의 1비트 스트림, SoundWire는 저전력 다중장치, USB Audio는 외장 DAC 연결에 흔히 쓰인다"},{"name":"스피커 — 보이스코일 · 영구자석 · 에어갭 · 콘/진동판 · 서스펜션 · 프레임 · 더스트캡","role":"보이스코일에 흐르는 전류가 영구자석의 에어갭 자기장 속에서 힘을 받아 왕복하고, 콘·진동판이 공기를 밀어 음파를 만든다 스파이더·서라운드(서스펜션)가 코일을 중심에 유지하고, 프레임(바스켓)이 전체를 지지, 더스트캡이 에어갭을 보호한다"},{"name":"마이크 — 콘덴서/일렉트릿(ECM) · MEMS · 다이나믹","role":"콘덴서·일렉트릿·MEMS는 진동판과 고정 백플레이트가 가변 축전기를 이뤄 간격 변화를 전압 변화로 바꾼다(바이어스 필요) MEMS는 실리콘 초소형 콘덴서 마이크로 전용 ASIC(증폭·변환, 아날로그 또는 PDM 출력)을 품어 폰·노트북에 들어간다 다이나믹(무빙코일)은 코일+자석으로 별도 전원 없이 동작한다"},{"name":"믹서 / 라우팅 / 음성 DSP 블록","role":"여러 입력·출력(스피커·이어폰·마이크·HDMI)을 섞고 경로를 정하며, 볼륨·이퀄라이저·에코 제거(AEC)·노이즈 억제·자동 이득(AGC)·능동 소음 제거(ANC)·마이크 어레이 빔포밍 같은 처리를 코덱·SoC·NPU 안에서 수행한다"},{"name":"아날로그 전원 · 기준전압 (LDO / 차지펌프 / 밴드갭)","role":"변환·증폭 단에 깨끗하고 안정된 전압을 공급한다 스위칭 잡음이 섞인 시스템 전원을 그대로 쓰면 험·잡음이 새어 들어오므로, 저잡음 LDO·차지펌프로 아날로그 레일을 분리하고 기준전압을 만든다"}],"model":"audio"},{"id":"camera","name":"웹캠","category":"입출력","summary":"빛을 받아 디지털 영상으로 바꿉니다","detail":"카메라·웹캠은 바깥세상의 빛(아날로그 광 신호)을 컴퓨터가 다룰 수 있는 디지털 픽셀 배열로 바꾸는 입력장치다 키보드가 손가락의 움직임을, 마이크가 공기의 떨림을 디지털로 바꾸듯, 카메라는 장면에서 반사된 빛의 세기와 색을 초당 수십 장의 프레임으로 표본화한다 특이한 점은 카메라 안에 이미 작은 컴퓨터(ISP·인코더)가 들어 있어, 센서가 뱉은 거친 원시 데이터를 스스로 보정하고 압축까지 마친 뒤 완성된 영상 스트림을 내보낸다는 것이다 그래서 컴퓨터 본체는 대개 '가공·압축된 영상'을 받아, 호스트(CPU 또는 GPU의 하드웨어 디코더)가 압축을 풀어 앱에 넘긴다","parts":[{"name":"렌즈 경통(다중 렌즈 요소)","role":"여러 장의 플라스틱·유리 렌즈를 겹쳐 빛을 센서 평면에 또렷이 모은다 매수(3P·5P 등)와 재질이 선명도·왜곡·화각을 좌우한다"},{"name":"조리개(Aperture/Iris)","role":"빛이 통과하는 구멍 크기(f값)로 들어오는 광량과 심도를 정한다 웹캠은 대개 고정 조리개(f/2.0 안팎)라 조절 날개가 없고, 밝기는 노출시간·게인으로 제어한다"},{"name":"IR 컷 필터(적외선 차단 필터)","role":"실리콘 센서가 민감한 근적외선을 걸러내, 사람 눈이 보는 색과 맞도록 정상화한다 (야간·얼굴인식용 IR 카메라는 반대로 이 필터 대신 IR 통과 필터를 쓴다.)"},{"name":"초점 액추에이터(VCM 보이스코일 모터)","role":"자동초점 모델에서 전류로 렌즈를 미세하게 앞뒤로 움직여 초점을 맞춘다 고정초점 웹캠에는 없다"},{"name":"CMOS 이미지 센서 다이","role":"수백만 개의 포토다이오드 화소가 격자로 박힌 반도체 칩 빛을 전하로 바꾸는 심장부이며, 화소·증폭기·읽기회로·컬럼 ADC가 한 칩에 집적된다"},{"name":"마이크로렌즈 어레이","role":"각 화소 맨 위에 얹힌 아주 작은 렌즈로, 빗겨 오는 빛까지 화소 중앙의 광 감지부로 모아 감도(집광 효율)를 높인다"},{"name":"베이어 컬러필터 어레이(CFA)","role":"마이크로렌즈 바로 아래에서 화소마다 R·G·B 중 한 색만 통과시키는 색 필터 초록을 빨강·파랑의 두 배로 배치(RGGB)해 사람 눈이 밝기에 예민한 초록 정보를 더 촘촘히 받는다"},{"name":"화소 읽기회로(액티브 픽셀 센서)","role":"화소마다 놓인 전송·리셋 트랜지스터와 소스 팔로워가, 부동확산(FD) 노드에서 전하를 전압으로 바꿔 행 단위로 읽어낸다 상관 이중 샘플링(CDS)으로 리셋 잡음을 줄인다"},{"name":"컬럼 ADC(아날로그-디지털 변환기)","role":"센서 열마다 병렬로 놓여, 화소 전압을 대략 10~12비트 디지털 값으로 바꾼다 열 병렬 구조가 빠른 프레임레이트를 가능케 한다"},{"name":"센서-ISP 인터페이스(MIPI CSI-2 등)","role":"센서가 만든 RAW 픽셀 스트림을 ISP/브리지 칩으로 나르는 고속 직렬 링크 여러 데이터 레인으로 초당 수 Gbps를 전송한다"},{"name":"ISP(이미지 신호처리기)","role":"RAW 데이터를 디모자이킹·노이즈 제거·화이트밸런스·감마·HDR로 가공하고, 자동노출·초점·화밸(3A)을 제어하는 카메라 속 전용 프로세서 흔히 인코더·USB와 함께 한 SoC에 통합된다"},{"name":"하드웨어 영상 인코더","role":"완성된 프레임을 MJPEG 또는 H.264/H.265로 압축해 USB 대역폭 안에 들어가게 만든다 전용 회로라 실시간으로 처리하며, 보통 브리지 SoC 안에 통합돼 있다"},{"name":"USB 브리지 컨트롤러(MCU, UVC)","role":"압축 스트림을 USB 비디오 클래스(UVC) 패킷으로 만들어 호스트로 전송하고, 노출·해상도 등 제어 명령을 받아 센서·ISP에 전달하는 지휘부"},{"name":"보조 요소(PCB·IR LED·마이크·상태 LED)","role":"모든 칩을 얹은 기판, 얼굴인식·야간용 적외선 조명, 함께 내장된 마이크(오디오 ADC), 촬영 중임을 알리는 표시(테일리)등 등"}],"model":"camera"},{"id":"nic","name":"네트워크 카드","category":"네트워크","summary":"컴퓨터와 네트워크 사이에서 데이터를 주고받습니다","detail":"CPU와 메모리가 다루는 디지털 데이터를, 바깥 네트워크 매체가 이해하는 형태(구리선의 전압 변화, 광섬유의 빛, 안테나의 전자기파)로 변환하고 그 역변환도 담당하는 하드웨어다 OSI 모델의 2계층(데이터링크)과 1계층(물리)을 실물 회로로 구현해, 데이터를 '프레임'이라는 규격 봉투에 담고 주소(MAC)를 붙이며 오류검출 도장(CRC)을 찍고 매체 접근을 통제한다 이때 유선(이더넷)은 스위치 기반 전이중으로 충돌 없이 주고받지만, 무선(Wi-Fi)은 공기를 공유하는 반이중이라 CSMA/CA로 충돌을 피하며 802.11 MAC/PHY를 구현한다 나아가 체크섬 계산이나 큰 데이터 쪼개기 같은 반복 작업을 하드웨어가 대신 처리(오프로드)해 CPU의 부담을 덜어준다 유선 이더넷 NIC와 무선 Wi-Fi 모듈은 매체가 다를 뿐 \"디지털 ↔ 물리신호 변환 관문\"이라는 본질은 같다","parts":[{"name":"MAC 컨트롤러 (Media Access Control)","role":"프레임을 조립·해체하고 MAC 주소를 붙이며 CRC(FCS)를 계산·검증하고, 매체 접근(유선 전이중/무선 CSMA/CA)과 송수신 큐를 관리하는 2계층의 두뇌 오늘날 PC에서는 흔히 칩셋/SoC 안에 통합돼 있다"},{"name":"PHY 트랜시버 (물리계층: PCS/PMA/PMD)","role":"비트를 선로 코드·심볼로 바꾸고(송신) 물리 신호에서 비트를 복원하며(수신), 스크램블링·등화·클럭 복원(SerDes)·오토니고시에이션을 담당하는 1계층 회로"},{"name":"자기소자 (격리 트랜스포머 + 공통모드 초크)","role":"두 기기의 접지 전위차를 끊어 갈바닉 절연·감전 보호를 하고, 공통모드 잡음을 상쇄하며 임피던스를 정합한다 RJ45에 통합되면 MagJack이라 부른다"},{"name":"RJ45 (8P8C) 커넥터","role":"랜케이블을 꽂는 8핀 물리 접점 여러 트위스트 페어를 통해 차동 신호가 드나드는 유선 이더넷의 출입구"},{"name":"Wi-Fi 베이스밴드/MAC 프로세서","role":"무선 프레임 조립, CSMA/CA 매체 접근, 암호화, QAM 매핑, OFDM/OFDMA 처리, MIMO 스트림 관리 등 무선 통신의 디지털 두뇌 대개 전용 펌웨어로 동작한다"},{"name":"RF 트랜시버 (믹서·PLL 신디사이저·ADC/DAC)","role":"베이스밴드 디지털 신호를 아날로그로 바꾸고(DAC), 국부발진기로 반송파 위로 주파수를 올리거나 내리는(믹서) 아날로그-디지털 경계"},{"name":"RF 프런트엔드 (PA·LNA·RF 스위치·SAW/BAW 필터)","role":"송신 신호를 증폭하는 PA(전력증폭기), 수신 신호를 잡음 적게 키우는 LNA(저잡음증폭기), 송수신을 전환하는 스위치, 원치 않는 주파수를 걸러내는 필터의 묶음"},{"name":"안테나","role":"전기 신호를 전자기파로 방사하고 되받는 변환기 Wi-Fi는 여러 개(다중 안테나)로 MIMO·빔포밍을 구현하며, 블루투스와 공유하기도 한다"},{"name":"블루투스 콤보 & 공존 로직","role":"같은 2.4 GHz 대역과 안테나를 쓰는 Wi-Fi·블루투스가 서로 간섭하지 않도록 시간을 나눠 조율하는 부분 노트북·폰의 콤보 칩에 함께 들어간다"},{"name":"host 버스 인터페이스 & DMA 엔진 (PCIe/USB/M.2)","role":"NIC를 컴퓨터 본체와 연결하고, 디스크립터 링을 읽어 CPU 개입 없이 메모리와 데이터를 직접 주고받는(DMA) 통로"},{"name":"온보드 버퍼·메모리 (FIFO/SRAM) 와 펌웨어 저장소(EEPROM/플래시)","role":"host와 링크의 속도 차를 흡수하는 송수신 버퍼, MAC 주소·설정을 담은 EEPROM, 동작 코드를 담은 펌웨어 플래시"},{"name":"클럭 소스 (크리스탈 오실레이터)","role":"정확한 심볼 타이밍과 반송파 주파수의 기준이 되는 진동자 무선에서는 주파수 정확도가 통신 품질을 좌우한다"},{"name":"상태 표시 LED / 오프로드·보안 가속 블록(서버급)","role":"링크·활동을 알리는 LED. 서버용 NIC에는 TCP 오프로드, 암호화 가속, 대형 패킷 버퍼 등 추가 가속 회로가 들어가기도 한다"}],"model":"nic"},{"id":"infra","name":"라우터·인터넷","category":"네트워크","summary":"목적지를 향해 패킷을 전달합니다","detail":"내 컴퓨터의 NIC에서 나온 패킷이 목적지 서버까지 갔다 오도록 실어 나르는 \"바깥 세계의 배관\"이다 집 안 공유기가 출입구를 지키고, 모뎀·ONT가 신호를 광으로 바꾸며, ISP·백본·해저케이블·IXP가 대륙을 잇고, DNS가 길 안내를, CDN이 지름길을 제공한다 CPU·RAM·SSD가 한 컴퓨터 안의 속도 계층이라면, 이 인프라는 전 세계 컴퓨터를 하나로 잇는 계층이며, 컴퓨터 아키텍처의 관점에서는 \"가장 느리고 가장 먼 메모리 계층\"에 해당한다 인터넷 왕복(RTT)은 대략 수십~수백 ms로, 약 0.3~1 ns인 레지스터·L1 캐시 접근에 견주면 어림잡아 수천만 배(대략 3천만~1억 배) 느린 셈이다 중앙 관제탑 없이 수많은 자율적 장비가 협력해 데이터를 릴레이하는, 인류가 만든 가장 큰 분산 기계다","parts":[{"name":"공유기 라우팅 엔진(SoC)","role":"공유기의 두뇌 패킷의 목적지 IP를 보고 어디로 보낼지 결정하고, NAT 주소 변환·DHCP 주소 배정·방화벽 규칙을 실행한다 저가형은 범용 CPU가, 고급형은 전용 하드웨어 가속기(네트워크 오프로드 엔진)가 처리한다"},{"name":"내장 이더넷 스위치","role":"공유기의 유선 LAN 포트 여러 개를 묶어, 집 안 유선 기기끼리 또는 유선↔무선 사이에서 MAC 주소를 기준으로 프레임을 전달하는 2계층(데이터 링크) 부품"},{"name":"무선 AP (라디오 + 베이스밴드 + 안테나)","role":"Wi-Fi 신호를 만들고 받는 부분 디지털 데이터를 전파로 변조·복조하고, 여러 안테나(MIMO)와 빔포밍으로 속도와 도달 거리를 높인다"},{"name":"모뎀 / ONT의 광 트랜시버","role":"레이저 다이오드(전기→빛)와 포토다이오드(빛→전기)로 신호 형태를 바꾸는 광↔전기 변환기 FTTH에서 가정 쪽 광 종단 역할을 한다"},{"name":"OLT (국사 쪽 광 종단)","role":"ISP 국사에서 한 가닥 광을 나눠 쓰는 수십~수백 가정의 ONT를 상대하는 집선 장비 ONT의 반대편 짝으로, 가입자 광선을 모아 코어망으로 넘긴다(PON 분기비는 보통 1:32~1:128)"},{"name":"ISP 에지/코어 라우터","role":"대형 캐리어급 라우터 여러 라인카드(고속 광 포트 다발)와 대용량 스위칭 패브릭, 초당 수억~수십억 개 패킷을 조회·전달하는 포워딩 ASIC을 갖추고 라우팅 테이블을 유지한다"},{"name":"광섬유 백본 링크 + DWDM 장비","role":"도시·국가를 잇는 장거리 유리섬유 간선 DWDM 다중화 장비가 여러 파장(색)을 한 섬유에 겹쳐 실어 한 가닥의 대역폭을 수십 배로 배가한다"},{"name":"해저 광케이블 + 중계기(EDFA)","role":"대륙을 잇는 해저 유리섬유 다발 수십~백 km마다 든 어븀 첨가 광증폭기(EDFA)가 감쇠한 빛을 전기 변환 없이 그대로 증폭한다 바깥은 강철선·구리(전력 공급용 도체)·폴리에틸렌으로 수압과 어선·닻으로부터 보호한다"},{"name":"IXP 스위칭 패브릭","role":"여러 네트워크 사업자·콘텐츠 사업자가 한 건물에 모여 서로 케이블을 꽂아 트래픽을 직접 교환하는 중립적 대형 스위치 먼 우회 없이 짧고 싸게 데이터를 주고받게 한다"},{"name":"CDN 엣지 서버 (캐시 스토리지)","role":"사용자 가까이 전 세계에 분산 배치된 서버 RAM·SSD에 인기 콘텐츠(영상·이미지·정적 파일)를 미리 담아 두고, 원 서버 대신 낮은 지연으로 빠르게 응답한다"},{"name":"DNS 서버 계층","role":"이름→IP 사전 재귀 리졸버(사용자 대신 찾아 주는 창구)와 루트·TLD·권한 서버(주소 원본을 계층으로 나눠 관리)로 구성된다"},{"name":"라우팅 테이블 & 프로토콜(BGP·OSPF)","role":"논리적 부품 어느 IP 대역이 어느 방향에 있는지 적힌 지도(라우팅 테이블)와, 그 지도를 서로 자동으로 갱신·공유하는 규약(BGP는 사업자 간, OSPF는 사업자 내부)"},{"name":"공유기 전원부·플래시·RAM","role":"어댑터로 받은 전기를 회로용 전압으로 바꾸는 전원부, 펌웨어(운영 코드)를 담은 플래시, 지나가는 패킷과 NAT 표를 잠시 담는 RAM. 공유기 자체가 작은 전용 컴퓨터임을 보여준다"}],"model":"infra"},{"id":"datacenter","name":"데이터센터","category":"네트워크","summary":"여러 서버가 모여 서비스의 요청을 처리합니다","detail":"데이터센터는 우리가 검색·스트리밍·게임 매칭·AI 질문을 할 때 그 계산과 저장을 실제로 떠맡는 곳이다 개인용 PC 한 대가 아니라 수천~수십만 대의 평범한 서버를 한 건물에 모아 초고속 네트워크로 엮고, 가상화·오케스트레이션 소프트웨어로 하나의 거대한 자원 풀처럼 빌려 쓴다 핵심 임무는 '연산(서버)·저장(스토리지)·전달(네트워크)'을 제공하면서 동시에 전력·냉각·물리 보안을 무중단으로 유지하는 것이다 즉 데이터센터의 진짜 제품은 IT 성능이 아니라 '가용성(멈추지 않음)'이며, 진정한 무중단은 한 건물 안의 이중화뿐 아니라 여러 데이터센터(지역·가용영역)로 분산해야 완성된다","parts":[{"name":"랙(Rack)과 랙유닛(U)","role":"장비를 세로로 꽂는 19인치 표준 골격 높이를 1U(약 44.45 mm) 단위로 세며 보통 42U 한 개당 서버·스위치 수십 개를 담는다 케이블·전원·냉각을 랙 단위로 표준화해 관리한다"},{"name":"서버(다소켓 CPU · 대용량 RAM · NIC)","role":"실제 연산을 하는 알맹이 보통 듀얼 소켓 CPU(합쳐 수십~수백 코어), 수백 GB~수 TB DDR5 RAM, 하나 이상의 고속 NIC를 얇은 1U~2U 섀시에 담는다 여러 대가 모여 하나의 자원 풀처럼 쓰인다"},{"name":"NIC(Network Interface Card)","role":"서버를 네트워크에 연결하는 카드 25/100/200/400 GbE 같은 고속 링크로 ToR 스위치와 이어지며, 패킷 처리 일부를 CPU 대신 떠맡는다(오프로드) AI용은 RDMA를 지원한다"},{"name":"DPU / 스마트NIC(SmartNIC)","role":"NIC를 넘어 자체 CPU·가속 엔진을 얹은 '네트워크 위의 작은 컴퓨터'. 가상 스위칭·방화벽·암호화·스토리지 접속 같은 인프라 일을 호스트 CPU 대신 처리해 성능·보안·격리를 끌어올린다(NVIDIA BlueField, AWS Nitro 등)"},{"name":"ToR 스위치(Top of Rack)","role":"랙 맨 위에 놓여 그 랙 안 서버 전부를 묶는 액세스 스위치 짧은 케이블로 서버를 모으고, 위쪽 스파인으로 올려보내는 첫 관문이다 리프-스파인 구조에서 '리프' 역할을 겸한다"},{"name":"스파인 스위치 / 리프-스파인 패브릭","role":"모든 리프(ToR)를 서로 이어주는 중앙 백본 리프↔스파인이 촘촘히 연결돼 다른 랙 간에는 같은 홉 수로 도달하며, 대규모 서버 간 트래픽을 막힘없이 흘린다 초대형은 super-spine을 얹어 3단으로 확장한다"},{"name":"로드밸런서(Load Balancer)","role":"들어오는 요청을 살아있는 서버들에 고르게 분배하는 교통정리 장치 대표 주소(VIP) 하나로 받아 뒤의 서버 풀로 나누고, 헬스체크로 죽은 서버는 자동 제외해 무중단을 만든다 L4/L7 두 층위로 동작한다"},{"name":"스토리지 계층(Storage Tier)","role":"데이터를 속도·비용에 따라 층으로 나눠 보관 로컬 NVMe SSD(핫) → 올플래시/분산 스토리지(웜) → HDD·테이프 아카이브(콜드) 순으로, 블록·파일·오브젝트 형태로 서버에 제공한다 내구성을 위해 복제·이레이저 코딩으로 여러 벌을 둔다"},{"name":"AI 가속기 클러스터(GPU/TPU)","role":"대규모 병렬 연산 전담 한 노드에 GPU/TPU 여러 개와 HBM을 얹고, 노드 안은 NVLink, 노드 간은 InfiniBand/RoCE로 엮어 하나의 거대한 계산기처럼 학습·추론을 나눠 처리한다"},{"name":"NVLink · InfiniBand 인터커넥트","role":"가속기끼리 데이터를 초고속·저지연으로 주고받는 전용 배선/망 NVLink(NVSwitch 포함)는 GPU 직결(신형은 랙 전체를 한 도메인으로), InfiniBand(또는 RoCE)는 서버를 넘는 RDMA 통신을 담당한다"},{"name":"UPS(무정전 전원장치)","role":"정전 순간 배터리(또는 플라이휠)로 전력을 즉시 이어받아 수 초~수 분을 버틴다 발전기가 기동해 안정될 때까지의 '공백'을 메워 서버가 꺼지지 않게 한다"},{"name":"비상 발전기(디젤 제너레이터)","role":"장시간 정전에 대비한 자체 발전소 정전 감지 후 대략 10초 안팎(NFPA 110 기준)에 부하를 받아 연료가 있는 한 건물 전체 전력을 공급한다 UPS와 짝을 이뤄 전력 이중화를 완성한다"},{"name":"배전 계통(스위치기어 · PDU · 서버 PSU)","role":"전기를 서버까지 나눠주는 사슬 고압을 받아 스위치기어가 분배하고, 랙 PDU(전원분배장치)가 A/B 두 계통으로 각 서버에 꽂아준다 서버 PSU가 최종적으로 12V DC로 바꾸며, 고밀도 AI 랙은 48V DC 랙버스나 고압 직류(HVDC)를 쓰는 추세다"},{"name":"냉각 시스템(핫/콜드 아일 · CRAC/CRAH · 칠러 · 냉수)","role":"서버 열을 밖으로 내보내는 순환계 콜드 아일로 찬 공기를 넣고 핫 아일로 더운 공기를 모아, 냉수(chilled water) 코일과 칠러·냉각탑으로 열을 버린다 고밀도 랙은 칩에 직접 붙는 직수랭(cold plate)·액침(immersion)을 쓴다"},{"name":"상면(Raised Floor)과 케이블·배관","role":"장비를 놓는 바닥 공간 전통적 이중 바닥(raised floor) 아래로 냉기·전원·케이블을 흘려보내며(고밀도 신설은 슬래브 바닥+오버헤드 배선도 많다), 상면 임대·설계가 데이터센터 용량의 기본 단위가 된다"},{"name":"관리·모니터링(DCIM · BMS · OOB)","role":"건물의 신경계 DCIM/BMS가 전력·온도·습도를, 서버의 BMC(대역외 관리, OOB)가 개별 하드웨어 상태를 상시 감시해 고장을 조기에 잡고 원격으로 대응한다"},{"name":"경계 라우터(Border/Edge Router)","role":"데이터센터와 인터넷 백본이 만나는 건물 가장자리의 라우터 BGP/Anycast로 트래픽을 받아 내부망(로드밸런서·리프-스파인)으로 넘기고 응답을 다시 인터넷으로 내보내며, 이 경계에서 DDoS 방어·필터링을 수행하는 North-South 트래픽의 첫·마지막 관문이다 문서의 작동 방식 1·8단계에서 핵심 역할로 등장하지만 주요 부품 표에는 빠져 있다"}],"model":"datacenter"},{"id":"coproc","name":"보조 프로세서","category":"연산","summary":"장치 안에서 특정 작업을 전담하는 작은 프로세서입니다","detail":"컴퓨터는 사실 '컴퓨터 한 대'가 아니라, 메인 CPU를 중심으로 수십 개의 작은 컴퓨터가 협업하는 연합체다 보조 프로세서와 마이크로컨트롤러(MCU)는 SSD·웹캠·키보드·전원부·팬 같은 곳에 숨어, 특정한 일 한 가지를 저전력·실시간·저비용으로 전담한다 이들이 반복적이고 전용적인 잔일을 떠맡아 주기 때문에 메인 CPU는 범용 계산에 집중할 수 있고, 물리적으로 가까운 곳에서 처리되어 버스 왕복이 줄며, 심지어 메인 CPU가 꺼진 상태에서도 일부 기능(전원 버튼 감시·배터리 충전·시계(RTC) 유지)이 계속 살아 있게 된다","parts":[{"name":"CPU 코어(연산 코어)","role":"명령을 실행하는 두뇌 임베디드에선 ARM Cortex-M, RISC-V, 옛 8051, AVR, MSP430 같은 작고 단순한 코어를 쓴다 참고로 8051·AVR·다수 DSP는 명령/데이터 버스를 분리한 하버드 계열이며, 하버드는 DSP만의 특징이 아니다"},{"name":"프로그램 메모리(ROM / 내장 플래시)","role":"펌웨어를 저장하는 비휘발성 메모리 전원이 꺼져도 지워지지 않아, 켜자마자 여기서 곧바로 코드를 실행한다 플래시는 재기록 가능해 펌웨어 업데이트가 된다(진짜 고정된 마스크 ROM은 일부에 불과)"},{"name":"데이터 메모리(내장 SRAM)","role":"실행 중 변수·스택·입출력 버퍼를 담는 휘발성 작업 공간 외장 DRAM 없이 칩 안의 이 SRAM만으로 동작하는 경우가 많다"},{"name":"클럭 시스템(오실레이터 + PLL)","role":"칩 전체의 동작 박자를 만든다 저속 오실레이터를 PLL로 체배해 코어 클럭을 얻고, 필요 없을 땐 클럭을 늦추거나 꺼서(클럭 게이팅) 전력을 아낀다"},{"name":"실시간 시계(RTC)","role":"저전력 별도 도메인에서 초·분·시를 계속 세는 시계 시스템이 꺼진 상태에서도 코인셀/대기 전원으로 동작해 날짜·시각을 유지하고, 예약 알람으로 시스템을 깨우는 웨이크업 소스가 된다"},{"name":"타이머/카운터 · 워치독 타이머","role":"시간을 재고 주기적 인터럽트를 발생시키며 PWM(모터·백라이트·팬 제어) 신호를 만든다 워치독은 펌웨어가 제때 '살아있다' 신호(kick)를 안 주면 칩을 강제 리셋해 멈춤에서 복구한다"},{"name":"인터럽트 컨트롤러(예: ARM NVIC)","role":"여러 사건에 우선순위를 매겨, 급한 일이 오면 진행 중이던 코드를 멈추고 해당 처리 루틴으로 즉시 점프시킨다 실시간 반응성의 관제탑"},{"name":"GPIO(범용 입출력 핀)","role":"칩과 바깥 회로를 잇는 디지털 신호선 버튼·LED·릴레이·다른 칩의 제어선을 읽고 쓴다"},{"name":"통신 주변장치(UART·SPI·I2C·I2S·USB·CAN)","role":"다른 칩·센서·호스트와 표준 규약으로 데이터를 주고받는 하드웨어 블록 코어가 비트/바이트 단위로 씨름하지 않도록 직렬 통신을 자동 처리한다"},{"name":"ADC / DAC(아날로그-디지털 변환기)","role":"센서의 아날로그 전압을 디지털 숫자로(ADC), 디지털 값을 아날로그 파형으로(DAC) 변환 마이크·온도센서·오디오 출력의 관문이다(저가 MCU는 ADC만 있고 DAC는 없는 경우도 많다)"},{"name":"MAC 유닛(하드웨어 곱셈-누산기)","role":"DSP의 심장 곱셈과 덧셈을 한 연산으로 묶어 필터·FFT·행렬곱을 한 클럭에 한 단계씩 진행시킨다 신호처리가 실시간으로 가능한 이유"},{"name":"DMA 컨트롤러","role":"CPU 코어를 거치지 않고 주변장치↔메모리 사이로 데이터 뭉치를 직접 나른다 코어는 그동안 다른 일을 하거나 잠들 수 있어 효율이 오른다"},{"name":"하드웨어 가속 블록(암호 엔진·ECC 엔진·ISP 파이프라인·보안 부팅 등)","role":"특정 작업만 처리하는 전용 고정기능 회로 소프트웨어로 하면 느릴 일을 회로로 굳혀 압도적으로 빠르고 저전력으로 처리하며, 서명 검증(보안 부팅)·키 저장 같은 보안 기능도 담당한다"},{"name":"내장 전원 관리·리셋/브라운아웃 회로","role":"코어 전압을 만들고(내장 LDO/레귤레이터) 슬립/웨이크를 제어하며, 전압이 불안정할 때 안전하게 리셋해 오동작을 막는다 초저전력 상시 동작을 뒷받침한다"}],"model":null},{"id":"mouse","name":"마우스","category":"입출력","summary":"움직임과 버튼 상태를 입력 보고서로 전달합니다","detail":"광학 센서와 스위치의 상태를 마우스 컨트롤러가 읽고 USB 또는 무선 연결로 전달합니다 입력 보고서는 운영체제와 애플리케이션을 거쳐 처리됩니다","parts":[{"name":"광학 센서","role":"표면의 변화를 읽어 상대적인 이동을 측정합니다"},{"name":"버튼 스위치","role":"누름과 뗌 상태를 감지합니다"},{"name":"컨트롤러","role":"센서와 버튼 상태를 입력 보고서로 만듭니다"}],"model":"mouse"},{"id":"vrm","name":"VRM","category":"기판·버스·전원","summary":"각 칩에 필요한 낮고 안정된 전압을 만듭니다","detail":"전원 공급 장치에서 받은 전압을 CPU와 메모리 등이 요구하는 전압으로 바꾸고 부하 변화에도 조절합니다 메인보드와 그래픽 카드 등 여러 곳에 전압 조정 회로가 있습니다","parts":[{"name":"전력 스테이지","role":"스위칭으로 전력을 제어합니다"},{"name":"초크·커패시터","role":"전류와 전압의 변동을 완화합니다"},{"name":"제어기","role":"출력 전압을 피드백받아 스위칭을 조절합니다"}],"model":"vrm"}],"edges":[{"id":"cpu--sram","a":"cpu","b":"sram","kind":"structure","ab":"L1·L2·L3 캐시와 레지스터 파일이 CPU 코어 내부에 통합돼 있다","ba":"CPU 코어 안에서 가장 빠른 기억 계층으로 동작한다"},{"id":"cpu--dram","a":"cpu","b":"dram","kind":"data","ab":"통합 메모리 컨트롤러(IMC)로 RAM에 직결해 실행 중 명령·데이터를 읽고 쓴다","ba":"CPU의 IMC·메모리 버스에 직접 붙어 주기억을 공급한다"},{"id":"cpu--gpu","a":"cpu","b":"gpu","kind":"data","ab":"드로우콜·연산 명령을 만들어 PCIe로 GPU에 넘긴다","ba":"CPU가 넘긴 명령을 받아 대규모 병렬로 처리한다"},{"id":"cpu--npu","a":"cpu","b":"npu","kind":"data","ab":"SoC에 함께 통합돼 AI 추론 작업을 NPU로 위임한다","ba":"CPU가 배분한 추론 연산을 저전력으로 전담한다"},{"id":"cpu--bus","a":"cpu","b":"bus","kind":"data","ab":"PCIe·DMI 컨트롤러를 내장해 고속 주변장치로 나가는 길목이다","ba":"CPU 내장 컨트롤러에서 출발하는 데이터 도로망"},{"id":"cpu--mainboard","a":"cpu","b":"mainboard","kind":"structure","ab":"소켓에 장착되고 칩셋(PCH)과 DMI 링크로 이어진다","ba":"CPU를 소켓에 꽂아 모든 부품과 배선으로 잇는다"},{"id":"cpu--power","a":"cpu","b":"power","kind":"power","ab":"VRM이 12V를 코어용 약 1V로 정밀 변환해 공급한다","ba":"시스템에서 전력을 가장 많이 먹는 부하라 전용 VRM이 붙는다"},{"id":"cpu--cooling","a":"cpu","b":"cooling","kind":"thermal","ab":"주 발열원이라 히트싱크·팬으로 식히며 못 식히면 스로틀링한다","ba":"CPU 다이의 열을 뽑아내는 것이 냉각의 1순위 목표"},{"id":"cpu--ssd","a":"cpu","b":"ssd","kind":"data","ab":"NVMe 명령으로 프로그램·데이터를 읽어 실행한다","ba":"PCIe로 CPU에 붙어 저장된 코드·데이터를 공급한다"},{"id":"cpu--spirom","a":"cpu","b":"spirom","kind":"data","ab":"전원 직후 리셋 벡터에서 UEFI 펌웨어의 첫 명령을 읽는다","ba":"부팅의 첫 코드를 CPU에 건네는 출발점"},{"id":"cpu--coproc","a":"cpu","b":"coproc","kind":"data","ab":"여러 보조 프로세서에 전용 작업을 맡기고 인터럽트로 소통한다","ba":"메인 CPU를 도와 특정 작업을 전담·오프로드한다"},{"id":"cpu--nic","a":"cpu","b":"nic","kind":"data","ab":"네트워크 패킷의 최종 처리(프로토콜 스택)를 담당한다","ba":"패킷을 CPU에 전달하고 체크섬·분할을 오프로드한다"},{"id":"cpu--input","a":"cpu","b":"input","kind":"data","ab":"입력 이벤트를 인터럽트로 받아 처리한다","ba":"키·클릭을 인터럽트로 CPU에 전달한다"},{"id":"cpu--audio","a":"cpu","b":"audio","kind":"data","ab":"PCM 오디오 스트림을 디코딩·믹싱해 오디오 경로로 보낸다","ba":"CPU가 만든 소리 데이터를 넘겨받는다"},{"id":"cpu--camera","a":"cpu","b":"camera","kind":"data","ab":"웹캠 영상을 인코딩·표시·분석한다","ba":"가공된 영상을 CPU/GPU로 올려보낸다"},{"id":"cpu--datacenter","a":"cpu","b":"datacenter","kind":"context","ab":"데이터센터 서버의 핵심 연산기","ba":"서버 내부는 다소켓 CPU 등 같은 하드웨어의 대규모 집합이다"},{"id":"gpu--vram","a":"gpu","b":"vram","kind":"structure","ab":"프레임버퍼·텍스처·모델 가중치를 전용 VRAM에 두고 초고속으로 읽는다","ba":"GPU 바로 옆에 직결돼 초당 수백 GB~수 TB 대역폭을 공급한다"},{"id":"gpu--display","a":"gpu","b":"display","kind":"data","ab":"완성한 프레임을 HDMI·DP로 모니터에 송출한다(스캔아웃)","ba":"GPU 프레임버퍼를 받아 화면의 빛으로 바꾼다"},{"id":"gpu--bus","a":"gpu","b":"bus","kind":"data","ab":"PCIe ×16으로 CPU·시스템과 가장 넓게 연결된다","ba":"시스템에서 가장 넓은 PCIe 레인을 쓰는 장치"},{"id":"gpu--mainboard","a":"gpu","b":"mainboard","kind":"structure","ab":"메인보드의 PCIe ×16 슬롯에 장착된다(외장 그래픽)","ba":"GPU를 꽂는 최상위 PCIe 슬롯을 제공한다"},{"id":"gpu--dram","a":"gpu","b":"dram","kind":"data","ab":"시스템 RAM의 에셋을 DMA로 VRAM에 복사해 온다","ba":"GPU로 넘어갈 데이터가 잠시 머무는 주기억"},{"id":"gpu--power","a":"gpu","b":"power","kind":"power","ab":"고전력 부하라 PSU의 보조 전원 커넥터를 따로 쓴다","ba":"GPU가 PSU 총용량을 좌우하는 큰 소비처"},{"id":"gpu--cooling","a":"gpu","b":"cooling","kind":"thermal","ab":"발열이 커 자체 쿨러(팬·베이퍼챔버)를 단다","ba":"CPU와 함께 시스템의 주 발열원"},{"id":"gpu--npu","a":"gpu","b":"npu","kind":"context","ab":"무거운 AI는 GPU 텐서코어가, 가벼운 추론은 NPU가 분담","ba":"대규모 학습·추론은 GPU가 맡고 NPU는 저전력 온디바이스 추론을 맡는 보완 관계"},{"id":"gpu--coproc","a":"gpu","b":"coproc","kind":"data","ab":"내부에 비디오 인코더/디코더(NVENC/NVDEC) 등 고정기능 엔진을 품는다","ba":"GPU 안의 전용 고정기능 블록도 일종의 보조 처리기"},{"id":"gpu--sram","a":"gpu","b":"sram","kind":"structure","ab":"셰이더 코어 곁의 SRAM이 병렬 연산을 뒷받침","ba":"GPU도 온칩 SRAM 캐시·레지스터로 셰이더 데이터를 담는다"},{"id":"gpu--camera","a":"gpu","b":"camera","kind":"data","ab":"웹캠 영상의 인코딩·디코딩을 가속","ba":"가공된 영상을 GPU가 인코딩(H.264/265)·표시한다"},{"id":"gpu--datacenter","a":"gpu","b":"datacenter","kind":"context","ab":"서버용 대규모 병렬 연산기","ba":"AI·렌더 팜은 GPU를 대량 집적한다"},{"id":"gpu--spirom","a":"gpu","b":"spirom","kind":"data","ab":"그래픽카드에는 GPU 초기화 펌웨어인 VBIOS(및 UEFI GOP 드라이버)가 담긴 SPI 플래시 롬이 있어, 전원 인가 시 GPU가 이를 읽어 클럭·전압·메모리 타이밍을 설정하고 부팅 화면 출력을 시작한다","ba":"SPI 플래시 롬이 GPU 전용 VBIOS를 보관해, OS·드라이버 로드 전에 GPU가 스스로 초기화하고 초기 디스플레이 출력을 하도록 만든다"},{"id":"gpu--ssd","a":"gpu","b":"ssd","kind":"data","ab":"DirectStorage·GPUDirect Storage로 NVMe SSD의 게임 에셋·AI 데이터를 CPU·시스템 메모리를 거의 거치지 않고 VRAM으로 직접 스트리밍하며, 압축된 데이터는 GPU가 직접 풀어 로딩 병목을 줄인다","ba":"SSD가 대용량 텍스처·모델 가중치를 GPU에 직접 공급하는 데이터 경로가 되어, 저장장치→VRAM 직행으로 CPU 부하와 로딩 지연을 던다"},{"id":"gpu--audio","a":"gpu","b":"audio","kind":"data","ab":"GPU는 내장 오디오 컨트롤러로 HDMI·DisplayPort 출력 스트림에 사운드를 함께 실어, 모니터·TV 스피커로 영상과 음성을 한 케이블로 내보낸다","ba":"오디오 데이터가 GPU의 HDMI/DP 디스플레이 출력에 패킷으로 실려 화면과 동기화되어 전달된다(OS에서 GPU가 별도의 HD 오디오 장치로 인식됨)"},{"id":"gpu--nic","a":"gpu","b":"nic","kind":"data","ab":"다중 노드 AI 학습·추론에서 GPUDirect RDMA로 GPU가 고속 NIC와 직접 데이터를 주고받아 CPU·시스템 메모리를 우회하고, 여러 서버의 GPU를 하나처럼 묶는다","ba":"고속 NIC(InfiniBand·이더넷)가 서버 간 GPU를 연결해 분산 학습의 GPU 대 GPU 통신을 담당하며, GPUDirect RDMA로 GPU 메모리에 직접 접근한다"},{"id":"npu--dram","a":"npu","b":"dram","kind":"data","ab":"모델 가중치·활성값을 메모리에서 읽으며 대역폭이 성능을 좌우한다","ba":"NPU에 가중치를 공급하는 저장소"},{"id":"npu--vram","a":"npu","b":"vram","kind":"context","ab":"(외장형) 가중치·중간값을 VRAM/공유 메모리에 상주시킨다","ba":"고대역 메모리로 NPU 연산을 뒷받침"},{"id":"npu--coproc","a":"npu","b":"coproc","kind":"context","ab":"도메인 특화 가속기의 일종으로 SoC에 통합된다","ba":"특정 연산(추론)을 전담하는 보조 프로세서"},{"id":"npu--datacenter","a":"npu","b":"datacenter","kind":"context","ab":"대규모 버전은 데이터센터의 AI 가속기 클러스터로 확장된다","ba":"서버 랙에 NPU/TPU/GPU 가속기를 집적한다"},{"id":"npu--power","a":"npu","b":"power","kind":"power","ab":"저전력·고효율(TOPS/W)로 설계돼 배터리 기기에 적합","ba":"전력 예산 안에서 추론을 처리하도록 급전"},{"id":"npu--bus","a":"npu","b":"bus","kind":"data","ab":"NPU는 온칩 인터커넥트(NoC)와 SoC 버스(AXI 등)를 통해 CPU·메모리 컨트롤러와 명령·데이터를 주고받고 통합 메모리에 접근하며, 내부 타일 간 데이터 이동도 온칩 네트워크가 담당한다","ba":"버스·인터커넥트는 SoC 안에서 NPU를 CPU·GPU·메모리 컨트롤러와 잇는 데이터 고속도로이며, NPU가 가중치·활성값을 대량으로 실어 나르는 트래픽이 이 인터커넥트 대역폭을 크게 소모하는 주요 트래픽원이 된다"},{"id":"npu--camera","a":"npu","b":"camera","kind":"data","ab":"NPU는 카메라가(ISP 후처리를 거쳐) 넘긴 이미지 프레임을 입력으로 받아 얼굴 인식·야간 모드·컴퓨테이셔널 포토그래피·Windows Hello 생체 인증 같은 신경망 추론을 수행한다","ba":"카메라·웹캠이 만든 영상 데이터는 ISP를 거쳐 NPU로 흘러가 실시간 비전 AI(얼굴 인식·장면 이해·컴퓨테이셔널 포토그래피)에 쓰이므로, 카메라는 NPU 추론의 핵심 입력원 중 하나다"},{"id":"npu--audio","a":"npu","b":"audio","kind":"data","ab":"NPU는 마이크·오디오 서브시스템에서 들어온 음성 스트림을 받아 웨이크워드 상시 감지, AI 노이즈 캔슬링, 실시간 음성 인식·자막 생성을 저전력으로 추론한다","ba":"오디오(마이크·코덱)가 캡처한 음성 신호는 NPU로 전달되어 상시 웨이크워드 감지와 통화 노이즈 제거·음성 인식에 사용되며, 이 always-on 처리가 NPU 저전력 활용의 대표 사례다"},{"id":"npu--sram","a":"npu","b":"sram","kind":"data","ab":"NPU는 외부 DRAM 왕복을 줄이기 위해 대용량 온칩 SRAM에 가중치·활성값·부분합을 상주시켜 재사용을 극대화하는 것이 처리량의 핵심이라, SRAM 용량·대역폭이 성능을 직접 좌우한다","ba":"온칩 SRAM은 NPU의 스크래치패드·가중치/활성값 버퍼로 대량 배치되어, 캐시 계층과 동일한 SRAM 셀 기술이 AI 가속기의 데이터 상주 공간을 이룬다"},{"id":"sram--dram","a":"sram","b":"dram","kind":"data","ab":"캐시가 놓치면(미스) RAM에서 캐시 라인을 채워 온다 — 메모리 계층","ba":"RAM 데이터를 코어 옆 캐시로 끌어와 지연을 숨긴다"},{"id":"sram--coproc","a":"sram","b":"coproc","kind":"data","ab":"MCU·컨트롤러도 내부 SRAM을 작업 메모리로 쓴다","ba":"작은 프로세서의 온칩 작업 메모리"},{"id":"sram--bus","a":"sram","b":"bus","kind":"data","ab":"캐시 부적중 시 라인 인출과 하위 계층 라이트백, 그리고 MESI 일관성을 위한 스누핑(버스 감시) 트래픽이 모두 온칩 인터커넥트·버스를 통해 오간다","ba":"버스·인터커넥트는 코어별 사설 캐시들 사이, 그리고 공유 L3·DRAM 사이의 데이터 전송과 일관성 메시지를 실어 나르는 물리 경로로, 캐시 계층의 동작이 인터커넥트 위에서 성립한다"},{"id":"sram--vram","a":"sram","b":"vram","kind":"data","ab":"GPU의 SRAM 캐시·레지스터는 연산 유닛과 느린 VRAM 사이에 놓인 상위 계층으로, 자주 쓰이는 텍스처·가중치 조각을 붙잡아 두어 VRAM의 긴 접근 지연과 대역폭 부담을 완화하는 완충 역할을 한다","ba":"VRAM은 GPU 온칩 L1/L2 캐시(SRAM)에서 미스가 났을 때 비로소 접근되는 하위 저장 계층이다"},{"id":"sram--spirom","a":"sram","b":"spirom","kind":"data","ab":"SRAM 캐시가 CAR(No-Eviction) 모드로 임시 주기억처럼 동작해, SPI 플래시의 펌웨어가 메모리 컨트롤러를 훈련하기 전 단계(SEC/PEI)를 넘길 수 있게 받쳐 준다","ba":"DRAM이 아직 없는 부팅 극초기에, 플래시에서 XIP로 실행되는 초기 펌웨어 코드는 스택·변수를 둘 주기억이 없어 CPU 내부 캐시를 임시 RAM으로 쓰는 Cache-as-RAM(CAR) 기법에 의존한다"},{"id":"dram--mainboard","a":"dram","b":"mainboard","kind":"structure","ab":"DIMM/SO-DIMM 슬롯에 장착된다","ba":"RAM 모듈을 꽂는 슬롯을 제공한다"},{"id":"dram--vram","a":"dram","b":"vram","kind":"context","ab":"둘 다 DRAM 계열 — VRAM은 GPU 전용 사촌","ba":"시스템 RAM과 데이터를 주고받는 그래픽 전용 DRAM"},{"id":"dram--hdd","a":"dram","b":"hdd","kind":"data","ab":"HDD 데이터도 DMA로 RAM에 올라와 처리된다","ba":"읽은 데이터를 RAM 캐시로 전달한다"},{"id":"dram--power","a":"dram","b":"power","kind":"power","ab":"휘발성이라 전원이 꺼지면 소멸하고, 절전 땐 셀프 리프레시로 내용을 지킨다","ba":"RAM 내용 유지를 위해 절전 중에도 소량 급전"},{"id":"dram--bus","a":"dram","b":"bus","kind":"data","ab":"메모리 버스(채널)로 CPU와 데이터를 주고받는다","ba":"고대역 메모리 채널을 이룬다"},{"id":"dram--ssd","a":"dram","b":"ssd","kind":"data","ab":"저장장치가 읽은 데이터를 담는 페이지 캐시이자, SSD 매핑·버퍼용 메모리","ba":"읽은 데이터를 DMA로 RAM 페이지 캐시에 올리고, 자체 DRAM 캐시엔 매핑 테이블을 둔다"},{"id":"dram--nic","a":"dram","b":"nic","kind":"data","ab":"NIC가 수신한 패킷을 DMA로 시스템 DRAM의 수신 링 버퍼에 직접 써 넣고 송신 데이터도 DRAM에서 읽어가므로, 네트워크 데이터가 파싱·처리되는 실제 작업 공간이 DRAM이다","ba":"NIC는 자체 온보드 메모리가 작아 송수신 디스크립터 링과 패킷 페이로드를 시스템 DRAM에 두고 DMA로 오가며, CPU는 그 DRAM 버퍼를 읽어 프로토콜 스택을 처리한다"},{"id":"dram--spirom","a":"dram","b":"spirom","kind":"data","ab":"전원 직후 DRAM은 초기화되지 않아 곧바로 쓸 수 없고, SPI 플래시 롬에 담긴 BIOS/UEFI 펌웨어가 먼저 실행되어 각 모듈의 SPD를 읽고 메모리 컨트롤러를 설정·트레이닝해야 비로소 DRAM이 정상 동작 상태가 된다","ba":"SPI 롬의 부트 펌웨어는 DRAM이 준비되기 전 극소량의 온칩 메모리에서 시작해 DRAM 초기화·트레이닝을 수행한 뒤, 커널과 자기 자신을 DRAM으로 올려 본격 실행으로 넘어간다"},{"id":"dram--cooling","a":"dram","b":"cooling","kind":"thermal","ab":"DIMM은 자체 능동 냉각 장치가 없어 히트스프레더와 주변 공기 흐름(케이스 팬·랙 공조)에 방열을 전적으로 의존한다","ba":"냉각의 방열 대상에는 CPU·GPU·VRAM·SSD뿐 아니라 시스템 메모리(DRAM)도 포함된다"},{"id":"dram--audio","a":"dram","b":"audio","kind":"data","ab":"DRAM은 오디오 스택이 채워 둔 재생·녹음 버퍼를 보관하고, DMA가 CPU를 거의 깨우지 않고 이 영역을 코덱과 주고받게 해 끊김 없는 재생·녹음을 뒷받침한다","ba":"재생할 PCM 샘플과 녹음된 PCM 표본이 담기는 링 버퍼가 RAM(DRAM)에 자리 잡고, 코덱의 DMA 엔진이 이 메모리에서 샘플을 읽어 내보내거나 받아 적는다"},{"id":"dram--datacenter","a":"dram","b":"datacenter","kind":"context","ab":"대용량 DRAM이 가장 대규모로 배치·소비되는 대표 현장이 데이터센터 서버이며, 메모리 집약 워크로드와 인메모리 캐시 등 DRAM 수요의 큰 축을 데이터센터가 담당한다","ba":"서버는 요청과 작업 데이터를 RAM에 올려 CPU가 빠르게 처리하도록 합니다"},{"id":"dram--coproc","a":"dram","b":"coproc","kind":"data","ab":"DRAM은 SSD 컨트롤러의 작업 메모리로 쓰이고, 저전력 상태에서의 셀프 리프레시 진입·유지는 EC 같은 관리용 MCU가 관장한다","ba":"SSD 컨트롤러(대표적 보조 프로세서)는 FTL 매핑 테이블·캐시를 위해 자체 외장 DRAM을 쓰거나 HMB로 호스트 DRAM을 빌리고, EC는 절전 진입 시 DRAM 셀프 리프레시와 전원 레일을 제어한다(⚙️·🔗 절전 시나리오)"},{"id":"vram--display","a":"vram","b":"display","kind":"data","ab":"스캔아웃 대상 프레임버퍼가 VRAM에 있어 디스플레이 엔진이 읽어 간다","ba":"화면에 뿌릴 픽셀의 원본이 담긴 메모리"},{"id":"vram--power","a":"vram","b":"power","kind":"power","ab":"고속·고발열이라 넉넉한 급전이 필요","ba":"전력 소비가 큰 고속 메모리"},{"id":"vram--cooling","a":"vram","b":"cooling","kind":"thermal","ab":"GDDR/HBM도 발열해 GPU 쿨러가 함께 식힌다","ba":"GPU 방열 대상에 포함"},{"id":"vram--bus","a":"vram","b":"bus","kind":"data","ab":"VRAM은 CPU·NVMe가 만든 프레임버퍼·텍스처·에셋을 PCIe 버스를 건너 받아 채워지며, Resizable BAR 설정이 CPU가 버스 너머로 접근할 수 있는 VRAM 범위를 결정한다","ba":"버스는 CPU가 접근할 VRAM 주소 공간과 장치 사이 데이터 전송 경로를 제공합니다"},{"id":"vram--datacenter","a":"vram","b":"datacenter","kind":"context","ab":"HBM급 VRAM이 가장 대규모로 집적·소비되는 현장이 데이터센터 GPU 클러스터이며, 모델이 GPU 한 장 VRAM에 안 들어가 여러 GPU의 VRAM을 나눠 쓰는 것이 데이터센터 AI의 기본 구도다","ba":"AI 가속기에서는 HBM 등 전용 메모리의 용량과 대역폭이 처리 성능에 영향을 줍니다"},{"id":"ssd--bus","a":"ssd","b":"bus","kind":"data","ab":"PCIe/NVMe(또는 SATA)로 시스템에 연결된다","ba":"저장장치를 잇는 고속 통로"},{"id":"ssd--mainboard","a":"ssd","b":"mainboard","kind":"structure","ab":"M.2 슬롯이나 SATA 포트에 꽂힌다","ba":"SSD를 장착하는 슬롯·포트를 제공"},{"id":"ssd--hdd","a":"ssd","b":"hdd","kind":"context","ab":"같은 비휘발성 저장 계층 — 속도의 SSD, 용량·가격의 HDD로 상호 보완","ba":"SSD와 함께 저장 계층을 이루는 대용량 짝"},{"id":"ssd--coproc","a":"ssd","b":"coproc","kind":"data","ab":"내장 SSD 컨트롤러가 FTL·ECC를 실행하는 보조 프로세서다","ba":"SSD 안의 컨트롤러 SoC"},{"id":"ssd--cooling","a":"ssd","b":"cooling","kind":"thermal","ab":"고속 NVMe는 발열이 커 방열판을 붙인다","ba":"NVMe 지속 성능을 위한 방열 대상"},{"id":"ssd--spirom","a":"ssd","b":"spirom","kind":"data","ab":"부트로더가 SSD에 있어 부팅 체인이 SPI 롬→SSD로 이어진다","ba":"펌웨어 다음 단계 코드를 담은 저장소"},{"id":"ssd--power","a":"ssd","b":"power","kind":"power","ab":"저전력이지만 안정 급전이 필요","ba":"SSD 회로에 안정된 전압을 공급한다"},{"id":"ssd--datacenter","a":"ssd","b":"datacenter","kind":"context","ab":"서버의 대용량 저장 계층","ba":"서버 스토리지는 NVMe SSD 어레이로 구성된다"},{"id":"hdd--bus","a":"hdd","b":"bus","kind":"data","ab":"SATA 인터페이스로 칩셋에 연결된다","ba":"기계식 드라이브를 잇는 버스(SATA)"},{"id":"hdd--mainboard","a":"hdd","b":"mainboard","kind":"structure","ab":"메인보드 SATA 포트(PCH)에 연결된다","ba":"HDD를 붙이는 SATA 포트를 제공"},{"id":"hdd--coproc","a":"hdd","b":"coproc","kind":"data","ab":"내장 컨트롤러가 헤드·모터·캐시를 제어한다","ba":"HDD 내부 제어 프로세서"},{"id":"hdd--power","a":"hdd","b":"power","kind":"power","ab":"스핀들 모터·액추에이터 구동 전력을 받는다","ba":"모터 구동용 12V·5V 공급"},{"id":"hdd--datacenter","a":"hdd","b":"datacenter","kind":"context","ab":"대용량 HDD의 최대 수요처가 데이터센터의 냉·아카이브 스토리지 어레이이며, 낮은 비용의 대용량 장기 보관을 데이터센터가 이 계층에서 담당한다","ba":"데이터센터는 자주 읽지 않는 대용량 데이터의 장기 보관에 HDD를 사용합니다"},{"id":"spirom--mainboard","a":"spirom","b":"mainboard","kind":"structure","ab":"메인보드에 납땜되고 칩셋을 통해 CPU 주소공간에 매핑된다","ba":"펌웨어 칩을 얹고 CPU에 연결한다"},{"id":"spirom--coproc","a":"spirom","b":"coproc","kind":"data","ab":"EC·ME/PSP 같은 보안 프로세서가 먼저 접근·검증한다","ba":"부팅 전 펌웨어를 읽는 보안 프로세서"},{"id":"mainboard--bus","a":"mainboard","b":"bus","kind":"structure","ab":"칩셋(PCH)이 저속·다수 장치를 모아 DMI로 CPU에 전달 — 버스의 물리 구현","ba":"버스 배선과 슬롯이 놓이는 기판"},{"id":"mainboard--power","a":"mainboard","b":"power","kind":"power","ab":"VRM이 보드 위에 실장돼 각 부품에 전원을 분배한다","ba":"전원을 받아 부품별로 나눠주는 배선판"},{"id":"mainboard--nic","a":"mainboard","b":"nic","kind":"structure","ab":"온보드 NIC/Wi-Fi가 칩셋에 붙어 있다","ba":"네트워크 칩을 얹는 기판"},{"id":"mainboard--audio","a":"mainboard","b":"audio","kind":"structure","ab":"온보드 오디오 코덱이 칩셋에 연결된다","ba":"오디오 코덱을 얹는 기판"},{"id":"mainboard--input","a":"mainboard","b":"input","kind":"structure","ab":"USB 포트(PCH)로 키보드·마우스를 받는다","ba":"입력장치용 USB 포트를 제공"},{"id":"mainboard--coproc","a":"mainboard","b":"coproc","kind":"structure","ab":"임베디드 컨트롤러(EC)가 전원·팬·키보드를 관리한다","ba":"보드에 상주하는 관리용 MCU"},{"id":"mainboard--cooling","a":"mainboard","b":"cooling","kind":"thermal","ab":"히트싱크·팬이 보드와 소켓 주위에 장착된다","ba":"냉각 부품이 얹히는 기판"},{"id":"mainboard--display","a":"mainboard","b":"display","kind":"data","ab":"메인보드 후면 I/O 패널의 영상 출력 포트(HDMI·DisplayPort)와 노트북 내장 패널용 eDP 배선이 CPU 내장 그래픽(iGPU) 출력을 화면으로 내보낸다","ba":"외장 GPU 없이 내장 그래픽만 쓰는 데스크톱은 모니터를 메인보드 후면 포트에 직접 꽂아 화면을 받고, 노트북 내장 디스플레이는 보드에서 eDP 신호를 받아 표시한다"},{"id":"bus--nic","a":"bus","b":"nic","kind":"data","ab":"PCIe로 네트워크 카드를 연결한다","ba":"네트워크 관문을 잇는 버스"},{"id":"bus--input","a":"bus","b":"input","kind":"data","ab":"USB로 키보드·마우스를 연결한다","ba":"입력장치 연결 버스(USB)"},{"id":"bus--audio","a":"bus","b":"audio","kind":"data","ab":"USB/온보드 링크로 오디오를 연결한다","ba":"오디오 데이터 경로"},{"id":"bus--camera","a":"bus","b":"camera","kind":"data","ab":"USB(UVC)로 웹캠 영상을 전송한다","ba":"카메라 연결 버스"},{"id":"bus--coproc","a":"bus","b":"coproc","kind":"data","ab":"DMA 엔진·인터럽트 컨트롤러가 버스 체계의 일부로 전송을 대행한다","ba":"CPU 개입 없는 전송을 맡는 버스 내 처리기"},{"id":"bus--display","a":"bus","b":"display","kind":"data","ab":"영상 링크를 나르는 통로","ba":"DisplayPort-over-USB-C 등 버스를 통해 신호가 오기도 한다"},{"id":"bus--datacenter","a":"bus","b":"datacenter","kind":"context","ab":"PCIe·NVLink·InfiniBand 같은 버스·인터커넥트가 가장 극단적인 대역폭·규모로 쓰이는 곳이 데이터센터이며, 리프-스파인 패브릭과 가속기 인터커넥트가 데이터센터 성능의 병목을 좌우한다","ba":"서버 내부에서 NIC↔CPU·RAM은 PCIe 버스로, 가속기끼리는 NVLink/NVSwitch로, 노드 간은 InfiniBand/RoCE로 이어진다"},{"id":"power--cooling","a":"power","b":"cooling","kind":"power","ab":"팬·펌프에 전원을 공급하고, PSU·VRM 자신도 발열한다","ba":"전원부 발열을 식히고 팬 전력을 받는다"},{"id":"power--datacenter","a":"power","b":"datacenter","kind":"power","ab":"데이터센터는 UPS·발전기로 전력을 이중화한다","ba":"무중단 급전 인프라를 갖춘다"},{"id":"power--audio","a":"power","b":"audio","kind":"power","ab":"앰프에 구동 전력을 공급","ba":"파워 앰프가 스피커 구동 전력을 받는다"},{"id":"power--nic","a":"power","b":"nic","kind":"power","ab":"네트워크 칩에 급전","ba":"송수신 회로·무선 증폭에 전력을 쓴다"},{"id":"power--display","a":"power","b":"display","kind":"power","ab":"디스플레이 패널과 백라이트는 특히 노트북에서 시스템 전체 소비전력의 큰 비중을 차지하는 대형 부하다","ba":"디스플레이가 화면을 켜려면 전원부로부터 안정된 패널·백라이트 전원을 받아야 하며, 절전·화면 꺼짐 시 전원부가 해당 레일을 차단한다"},{"id":"power--coproc","a":"power","b":"coproc","kind":"power","ab":"노트북·서버에서는 임베디드 컨트롤러(EC)나 전용 전력관리 MCU가 전원 시퀀싱, 전원 버튼 입력 처리, 충전 IC·BMS 감독을 지휘한다","ba":"EC/전력관리 MCU는 전원부의 충전 회로와 배터리 상태(전압·온도·잔량)를 실시간 감시·제어하고, Power Good과 전원 시퀀스를 관리해 시스템 전원의 온/오프를 조율한다"},{"id":"power--input","a":"power","b":"input","kind":"power","ab":"전원부는 메인보드 USB 포트를 통해 입력장치에 버스 전원을 공급하고, 무선 장치의 경우 배터리가 유일한 동력원이 되어 배터리 잔량·전압 상태가 장치의 동작 여부와 무선 폴링 지연에 직접 영향을 준다","ba":"무선 키보드·마우스·게임패드는 내장 배터리로 구동되고, 유선 장치는 USB 버스 전원(5V)을 받아 센서·MCU·LED·햅틱 모터를 켠다"},{"id":"cooling--datacenter","a":"cooling","b":"datacenter","kind":"thermal","ab":"데이터센터 냉각 인프라","ba":"핫/콜드 아일·냉수로 대규모 방열한다"},{"id":"cooling--coproc","a":"cooling","b":"coproc","kind":"data","ab":"냉각의 되먹임 루프 — 온도 센서(DTS) 값을 팬커브에 대입해 PWM으로 팬·펌프 속도를 조절하고, 팬 tach로 고장을 감지하며, 열 셧다운을 트리거하는 열관리 제어 로직은 메인보드의 임베디드 컨트롤러(EC)·Super I/O 같은 보조 MCU가 실행한다","ba":"EC/Super I/O(보조 MCU)의 핵심 임무 중 하나가 팬 tach 입력 읽기, PWM 출력 생성, 온도 기반 팬커브 실행, 팬 고장·과열 시 열 셧다운 트리거 같은 시스템 열관리다"},{"id":"display--input","a":"display","b":"input","kind":"context","ab":"터치스크린은 디스플레이와 정전용량 입력이 한 몸이 된 형태","ba":"디스플레이 위에 입력 격자를 얹은 결합 장치"},{"id":"display--audio","a":"display","b":"audio","kind":"data","ab":"HDMI·DisplayPort 영상 링크는 픽셀뿐 아니라 오디오 신호도 함께 실어 나르며, 스피커 내장 모니터·TV에서는 이 링크가 곧 소리 출력 경로를 겸한다","ba":"오디오 신호가 별도 케이블 없이 디스플레이 링크(HDMI/DP)에 얹혀 전달되므로, 디스플레이 장치는 내장 스피커를 통한 오디오 출력의 실제 경로 중 하나가 된다"},{"id":"input--coproc","a":"input","b":"coproc","kind":"data","ab":"키 매트릭스를 스캔하는 키보드 MCU가 스캔코드를 만든다","ba":"입력을 1차 처리하는 전용 MCU"},{"id":"audio--coproc","a":"audio","b":"coproc","kind":"data","ab":"오디오 코덱·DSP가 DAC/ADC와 신호 처리를 맡는다","ba":"소리 변환·처리를 전담하는 보조 칩"},{"id":"audio--nic","a":"audio","b":"nic","kind":"data","ab":"블루투스 무선 이어폰·스피커로 소리를 보낼 때 PCM을 SBC/AAC/LC3 등으로 부호화한 스트림이 무선 모듈(대개 Wi-Fi·블루투스 콤보)을 통해 전송되므로 무선 오디오 경로는 이 모듈에 의존한다","ba":"Wi-Fi·블루투스 콤보 모듈의 블루투스 라디오가 압축된 오디오 스트림을 무선으로 실어 날라, 유선 잭 없이 재생·통화를 가능하게 한다"},{"id":"audio--camera","a":"audio","b":"camera","kind":"data","ab":"오디오 서브시스템(코덱·DSP)이 웹캠 내장 마이크 입력을 USB 오디오(UAC)로 받아 처리하고, 영상 프레임과의 립싱크(입 모양-소리 동기)를 맞춘다","ba":"웹캠에 내장된 마이크나 별도 마이크가 소리를 디지털화하고 영상과 동기를 맞춥니다"},{"id":"camera--coproc","a":"camera","b":"coproc","kind":"data","ab":"ISP(이미지 신호 프로세서)가 센서 raw를 컬러 영상으로 가공한다","ba":"카메라 raw를 다듬는 전용 프로세서"},{"id":"camera--nic","a":"camera","b":"nic","kind":"data","ab":"화상통화 때 인코딩된 영상이 네트워크로 나간다","ba":"영상 스트림을 실어 나르는 관문"},{"id":"nic--infra","a":"nic","b":"infra","kind":"data","ab":"공유기·모뎀을 거쳐 인터넷으로 나가는 내 컴퓨터의 관문","ba":"가정 관문에서 인터넷으로 이어지는 첫 장비가 NIC"},{"id":"nic--coproc","a":"nic","b":"coproc","kind":"data","ab":"베이스밴드·오프로드 프로세서가 변복조·패킷 처리를 맡는다","ba":"무선/유선 신호를 처리하는 전용 프로세서"},{"id":"nic--datacenter","a":"nic","b":"datacenter","kind":"data","ab":"서버-네트워크 연결 장치","ba":"서버마다 고속 NIC로 스위치·네트워크에 연결된다"},{"id":"infra--datacenter","a":"infra","b":"datacenter","kind":"data","ab":"ISP·백본·해저케이블을 거쳐 데이터센터 서버에 도달한다","ba":"인터넷 인프라 반대편의 종착지"},{"id":"datacenter--coproc","a":"datacenter","b":"coproc","kind":"context","ab":"각 서버에는 대역외(OOB) 관리를 담당하는 BMC(베이스보드 관리 컨트롤러)가 있어 전원·센서·펌웨어를 원격 감시·제어하고, DPU/스마트NIC도 자체 프로세서를 얹는다","ba":"BMC 같은 관리용 MCU/보조 프로세서가 수만 대 서버를 무인·원격으로 운용 가능하게 만드는 핵심이며, 데이터센터가 이런 관리 프로세서의 대표 활용처다"},{"id":"mouse--input","a":"mouse","b":"input","kind":"structure","ab":"마우스는 움직임과 클릭을 전달하는 입력장치의 한 종류입니다","ba":"입력장치에는 키보드뿐 아니라 마우스도 포함됩니다"},{"id":"mouse--bus","a":"mouse","b":"bus","kind":"data","ab":"USB 등의 연결로 입력 보고서를 호스트에 보냅니다","ba":"호스트 컨트롤러가 마우스의 보고서를 받아 시스템에 전달합니다"},{"id":"mouse--cpu","a":"mouse","b":"cpu","kind":"data","ab":"보고서는 드라이버와 운영체제를 거쳐 애플리케이션에 전달됩니다","ba":"CPU에서 실행되는 프로그램이 마우스 입력을 해석하고 상태를 갱신합니다"},{"id":"mouse--power","a":"mouse","b":"power","kind":"power","ab":"유선 장치는 USB 전원으로, 무선 장치는 배터리로 동작합니다","ba":"공급된 전력이 센서와 마우스 컨트롤러를 작동시킵니다"},{"id":"power--vrm","a":"power","b":"vrm","kind":"power","ab":"PSU 등의 전원에서 받은 전압이 전압 조정 회로에 들어갑니다","ba":"VRM이 칩에 필요한 전압으로 변환합니다"},{"id":"vrm--cpu","a":"vrm","b":"cpu","kind":"power","ab":"CPU 부하에 맞춰 낮고 안정된 전압을 공급합니다","ba":"CPU가 요구하는 전류가 바뀌면 VRM도 출력을 조절합니다"},{"id":"vrm--mainboard","a":"vrm","b":"mainboard","kind":"structure","ab":"메인보드의 전원부에 실장됩니다","ba":"기판은 VRM과 CPU·메모리를 전원 배선으로 이어줍니다"},{"id":"vrm--cooling","a":"vrm","b":"cooling","kind":"thermal","ab":"전압 변환 과정에서 발생한 열을 방출해야 합니다","ba":"방열판과 공기 흐름이 전원부의 온도를 낮춥니다"},{"id":"vrm--dram","a":"vrm","b":"dram","kind":"power","ab":"메모리 전원 계통은 DRAM이 사용할 전압을 조정합니다","ba":"DDR5 모듈의 PMIC 등 실제 조정 회로의 위치는 플랫폼과 규격에 따라 다릅니다"}]};
